declare
  v_period_key text := upper(coalesce(p_period_key, '12M'));
  v_start_date date;
  v_end_date date := current_date;
  v_previous_start_date date;
  v_previous_end_date date;
  v_period_label text;
  v_bucket_interval interval;
  v_bucket_format text;
  v_period_days integer;
  v_current_revenue numeric := 0;
  v_previous_revenue numeric := 0;
  v_current_orders integer := 0;
  v_previous_customers integer := 0;
  v_current_customers integer := 0;
  v_repeat_customers integer := 0;
  v_carts_with_items integer := 0;
  v_converted_carts integer := 0;
  v_visit_count integer := 0;
  v_product_view_count integer := 0;
  v_add_to_cart_count integer := 0;
  v_purchase_count integer := 0;
  v_avg_review_score numeric := 0;
  v_revenue_growth numeric := 0;
  v_new_customers_growth numeric := 0;
  v_repeat_purchase_rate numeric := 0;
  v_cart_abandonment_rate numeric := 0;
  v_conversion_rate numeric := 0;
  v_kpi_cards jsonb;
  v_revenue_growth_chart jsonb;
  v_customer_growth_chart jsonb;
  v_category_revenue_split jsonb;
  v_conversion_funnel jsonb;
  v_weekly_sales_pattern jsonb;
  v_performance_breakdown jsonb;
  v_result public.analytics;
begin
  case v_period_key
    when '7D' then
      v_start_date := v_end_date - interval '6 days';
      v_period_label := 'Last 7 days';
      v_bucket_interval := interval '1 day';
      v_bucket_format := 'Dy';
    when '30D' then
      v_start_date := v_end_date - interval '29 days';
      v_period_label := 'Last 30 days';
      v_bucket_interval := interval '1 day';
      v_bucket_format := 'DD Mon';
    when '3M' then
      v_start_date := (v_end_date - interval '3 months' + interval '1 day')::date;
      v_period_label := 'Last 3 months';
      v_bucket_interval := interval '1 month';
      v_bucket_format := 'Mon';
    when '12M' then
      v_start_date := (v_end_date - interval '12 months' + interval '1 day')::date;
      v_period_label := 'Last 12 months';
      v_bucket_interval := interval '1 month';
      v_bucket_format := 'Mon';
    else
      raise exception 'Unsupported analytics period key: %. Expected 7D, 30D, 3M, or 12M.', p_period_key;
  end case;

  v_period_days := (v_end_date - v_start_date + 1);
  v_previous_end_date := v_start_date - interval '1 day';
  v_previous_start_date := v_previous_end_date - (v_period_days - 1);

  select coalesce(sum(o.total), 0), count(*)
  into v_current_revenue, v_current_orders
  from public.orders o
  where o.created_at::date between v_start_date and v_end_date;

  select coalesce(sum(o.total), 0)
  into v_previous_revenue
  from public.orders o
  where o.created_at::date between v_previous_start_date and v_previous_end_date;

  select count(*)
  into v_current_customers
  from public.customers c
  where c.created_at::date between v_start_date and v_end_date;

  select count(*)
  into v_previous_customers
  from public.customers c
  where c.created_at::date between v_previous_start_date and v_previous_end_date;

  select count(*)
  into v_repeat_customers
  from public.customers c
  where c.created_at::date between v_start_date and v_end_date
    and coalesce(c.total_orders, 0) > 1;

  select count(distinct ci.cart_id)
  into v_carts_with_items
  from public.cart_items ci
  join public.carts c on c.id = ci.cart_id
  where ci.created_at::date between v_start_date and v_end_date;

  select count(distinct c.id)
  into v_converted_carts
  from public.carts c
  join public.cart_items ci on ci.cart_id = c.id
  join public.orders o on o.user_id = c.user_id and o.created_at >= c.created_at
  where ci.created_at::date between v_start_date and v_end_date;

  select count(*)
  into v_visit_count
  from public.activity_logs al
  where al.created_at::date between v_start_date and v_end_date
    and (al.action ilike '%visit%' or al.action ilike '%view_store%' or al.module ilike '%visit%');

  select count(*)
  into v_product_view_count
  from public.activity_logs al
  where al.created_at::date between v_start_date and v_end_date
    and (
      al.action ilike '%product%view%'
      or al.action ilike '%view_product%'
      or (al.action ilike '%view%' and al.module ilike '%product%')
    );

  select count(*)
  into v_add_to_cart_count
  from public.cart_items ci
  where ci.created_at::date between v_start_date and v_end_date;

  select count(*)
  into v_purchase_count
  from public.orders o
  where o.created_at::date between v_start_date and v_end_date;

  select coalesce(avg(p.rating), 0)
  into v_avg_review_score
  from public.products p
  where p.rating is not null;

  v_revenue_growth := case
    when v_previous_revenue > 0 then ((v_current_revenue - v_previous_revenue) / v_previous_revenue) * 100
    when v_current_revenue > 0 then 100
    else 0
  end;

  v_new_customers_growth := case
    when v_previous_customers > 0 then ((v_current_customers - v_previous_customers)::numeric / v_previous_customers) * 100
    when v_current_customers > 0 then 100
    else 0
  end;

  v_repeat_purchase_rate := case
    when v_current_customers > 0 then (v_repeat_customers::numeric / v_current_customers) * 100
    else 0
  end;

  v_cart_abandonment_rate := case
    when v_carts_with_items > 0 then greatest(0, ((v_carts_with_items - v_converted_carts)::numeric / v_carts_with_items) * 100)
    else 0
  end;

  v_conversion_rate := case
    when v_visit_count > 0 then (v_purchase_count::numeric / v_visit_count) * 100
    when v_carts_with_items > 0 then (v_purchase_count::numeric / v_carts_with_items) * 100
    else 0
  end;

  v_kpi_cards := jsonb_build_array(
    jsonb_build_object(
      'icon', 'pi pi-dollar',
      'title', 'Total Revenue',
      'value', 'GBP ' || to_char(round(v_current_revenue, 2), 'FM999G999G999G990D00'),
      'change', case when v_revenue_growth >= 0 then '+' else '' end || round(v_revenue_growth, 1)::text || '%',
      'changeLabel', 'vs previous period',
      'tone', case when v_revenue_growth >= 0 then 'positive' else 'negative' end
    ),
    jsonb_build_object(
      'icon', 'pi pi-chart-line',
      'title', 'Revenue Growth',
      'value', round(v_revenue_growth, 1)::text || '%',
      'change', case when v_revenue_growth >= 0 then '+' else '' end || round(v_revenue_growth, 1)::text || '%',
      'changeLabel', 'vs previous period',
      'tone', case when v_revenue_growth >= 0 then 'positive' else 'negative' end
    ),
    jsonb_build_object(
      'icon', 'pi pi-percentage',
      'title', 'Conversion Rate',
      'value', round(v_conversion_rate, 2)::text || '%',
      'change', '',
      'changeLabel', 'from available activity',
      'tone', 'neutral'
    ),
    jsonb_build_object(
      'icon', 'pi pi-shopping-cart',
      'title', 'Avg Order Value',
      'value', 'GBP ' || to_char(round(case when v_current_orders > 0 then v_current_revenue / v_current_orders else 0 end, 2), 'FM999G999G999G990D00'),
      'change', '',
      'changeLabel', 'current period',
      'tone', 'neutral'
    )
  );

  with buckets as (
    select generate_series(
      date_trunc(case when v_bucket_interval = interval '1 month' then 'month' else 'day' end, v_start_date::timestamp),
      date_trunc(case when v_bucket_interval = interval '1 month' then 'month' else 'day' end, v_end_date::timestamp),
      v_bucket_interval
    ) as bucket_start
  ),
  revenue as (
    select
      date_trunc(case when v_bucket_interval = interval '1 month' then 'month' else 'day' end, o.created_at) as bucket_start,
      sum(o.total) as revenue
    from public.orders o
    where o.created_at::date between v_start_date and v_end_date
    group by 1
  )
  select jsonb_build_object(
    'labels', coalesce(jsonb_agg(to_char(b.bucket_start, v_bucket_format) order by b.bucket_start), '[]'::jsonb),
    'revenue', coalesce(jsonb_agg(coalesce(round(r.revenue, 2), 0) order by b.bucket_start), '[]'::jsonb)
  )
  into v_revenue_growth_chart
  from buckets b
  left join revenue r on r.bucket_start = b.bucket_start;

  with buckets as (
    select generate_series(
      date_trunc(case when v_bucket_interval = interval '1 month' then 'month' else 'day' end, v_start_date::timestamp),
      date_trunc(case when v_bucket_interval = interval '1 month' then 'month' else 'day' end, v_end_date::timestamp),
      v_bucket_interval
    ) as bucket_start
  ),
  customer_counts as (
    select
      date_trunc(case when v_bucket_interval = interval '1 month' then 'month' else 'day' end, c.created_at) as bucket_start,
      count(*) filter (where coalesce(c.total_orders, 0) <= 1) as new_customers,
      count(*) filter (where coalesce(c.total_orders, 0) > 1) as returning_customers
    from public.customers c
    where c.created_at::date between v_start_date and v_end_date
    group by 1
  )
  select jsonb_build_object(
    'labels', coalesce(jsonb_agg(to_char(b.bucket_start, v_bucket_format) order by b.bucket_start), '[]'::jsonb),
    'newCustomers', coalesce(jsonb_agg(coalesce(cc.new_customers, 0) order by b.bucket_start), '[]'::jsonb),
    'returningCustomers', coalesce(jsonb_agg(coalesce(cc.returning_customers, 0) order by b.bucket_start), '[]'::jsonb)
  )
  into v_customer_growth_chart
  from buckets b
  left join customer_counts cc on cc.bucket_start = b.bucket_start;

  select coalesce(
    jsonb_agg(jsonb_build_object('label', category_name, 'value', round(revenue, 2)) order by revenue desc),
    '[]'::jsonb
  )
  into v_category_revenue_split
  from (
    select coalesce(cat.name, 'Uncategorized') as category_name, sum(oi.total) as revenue
    from public.orders o
    join public.order_items oi on oi.order_id = o.id
    left join public.products p on p.id = oi.product_id
    left join public.categories cat on cat.id = p.category_id
    where o.created_at::date between v_start_date and v_end_date
    group by coalesce(cat.name, 'Uncategorized')
  ) category_revenue;

  with raw_steps as (
    select *
    from (
      values
        (1, 'Visits', v_visit_count),
        (2, 'Product Views', v_product_view_count),
        (3, 'Add to Cart', v_add_to_cart_count),
        (4, 'Purchase', v_purchase_count)
    ) as step_data(step_number, step_label, step_value)
    where step_value > 0
  ),
  numbered_steps as (
    select
      row_number() over (order by step_number) as step,
      step_label,
      step_value,
      first_value(step_value) over (order by step_number rows between unbounded preceding and unbounded following) as first_step_value,
      lag(step_value) over (order by step_number) as previous_step_value
    from raw_steps
  )
  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'step', step,
        'label', step_label,
        'value', step_value,
        'percentage', case when first_step_value > 0 then round((step_value::numeric / first_step_value) * 100, 1) else 0 end,
        'dropOff', case when previous_step_value is null then null else greatest(previous_step_value - step_value, 0) end
      )
      order by step
    ),
    '[]'::jsonb
  )
  into v_conversion_funnel
  from numbered_steps;

  with weekdays as (
    select *
    from (
      values
        (1, 'Mon'),
        (2, 'Tue'),
        (3, 'Wed'),
        (4, 'Thu'),
        (5, 'Fri'),
        (6, 'Sat'),
        (7, 'Sun')
    ) as weekday_data(day_number, day_label)
  ),
  sales as (
    select extract(isodow from o.created_at)::integer as day_number, sum(o.total) as revenue
    from public.orders o
    where o.created_at::date between v_start_date and v_end_date
    group by 1
  )
  select jsonb_build_object(
    'labels', jsonb_agg(w.day_label order by w.day_number),
    'revenue', jsonb_agg(coalesce(round(s.revenue, 2), 0) order by w.day_number)
  )
  into v_weekly_sales_pattern
  from weekdays w
  left join sales s on s.day_number = w.day_number;

  v_performance_breakdown := jsonb_build_array(
    jsonb_build_object(
      'label', 'Revenue Growth (Period)',
      'value', round(v_revenue_growth, 1),
      'displayValue', round(v_revenue_growth, 1)::text || '%',
      'tone', case when v_revenue_growth >= 0 then 'positive' else 'negative' end
    ),
    jsonb_build_object(
      'label', 'New Customers Growth',
      'value', round(v_new_customers_growth, 1),
      'displayValue', round(v_new_customers_growth, 1)::text || '%',
      'tone', case when v_new_customers_growth >= 0 then 'positive' else 'negative' end
    ),
    jsonb_build_object(
      'label', 'Repeat Purchase Rate',
      'value', round(v_repeat_purchase_rate, 1),
      'displayValue', round(v_repeat_purchase_rate, 1)::text || '%',
      'tone', 'neutral'
    ),
    jsonb_build_object(
      'label', 'Cart Abandonment Rate',
      'value', round(v_cart_abandonment_rate, 1),
      'displayValue', round(v_cart_abandonment_rate, 1)::text || '%',
      'tone', case when v_cart_abandonment_rate > 50 then 'negative' else 'positive' end
    ),
    jsonb_build_object(
      'label', 'Avg Review Score',
      'value', round((v_avg_review_score / 5) * 100, 1),
      'displayValue', round(v_avg_review_score, 2)::text || '/5',
      'tone', 'neutral'
    )
  );

  insert into public.analytics (
    period_key,
    period_label,
    start_date,
    end_date,
    kpi_cards,
    revenue_growth_chart,
    customer_growth_chart,
    category_revenue_split,
    conversion_funnel,
    weekly_sales_pattern,
    performance_breakdown,
    updated_at
  )
  values (
    v_period_key,
    v_period_label,
    v_start_date,
    v_end_date,
    v_kpi_cards,
    v_revenue_growth_chart,
    v_customer_growth_chart,
    v_category_revenue_split,
    v_conversion_funnel,
    v_weekly_sales_pattern,
    v_performance_breakdown,
    now()
  )
  on conflict (period_key, start_date, end_date)
  do update set
    period_label = excluded.period_label,
    kpi_cards = excluded.kpi_cards,
    revenue_growth_chart = excluded.revenue_growth_chart,
    customer_growth_chart = excluded.customer_growth_chart,
    category_revenue_split = excluded.category_revenue_split,
    conversion_funnel = excluded.conversion_funnel,
    weekly_sales_pattern = excluded.weekly_sales_pattern,
    performance_breakdown = excluded.performance_breakdown,
    updated_at = now()
  returning * into v_result;

  return v_result;
end;

declare
  v_user_id uuid := auth.uid();
  v_review_id uuid;
begin
  if v_user_id is null then raise exception 'Authentication required' using errcode = '42501'; end if;
  if p_rating not between 1 and 5 then raise exception 'Rating must be between 1 and 5' using errcode = '22023'; end if;
  if length(trim(coalesce(p_comment, ''))) not between 1 and 1000 then raise exception 'Comment length is invalid' using errcode = '22023'; end if;

  insert into public.reviews (product_id, user_id, rating, comment, status)
  values (p_product_id, v_user_id, p_rating, trim(p_comment), 'published')
  returning id into v_review_id;
  return v_review_id;
end;

begin
  if auth.uid() is null then raise exception 'Authentication required' using errcode = '42501'; end if;
  if p_rating not between 1 and 5 then raise exception 'Rating must be between 1 and 5' using errcode = '22023'; end if;
  if length(trim(coalesce(p_comment, ''))) not between 1 and 1000 then raise exception 'Comment length is invalid' using errcode = '22023'; end if;

  update public.reviews
  set rating = p_rating,
    comment = trim(p_comment),
    status = 'published'
  where id = p_review_id and user_id = auth.uid();
  if not found then raise exception 'Review not found' using errcode = 'P0002'; end if;
end;

declare
  v_user_id uuid := auth.uid();
  v_cart_id uuid;
  v_order_id uuid;
  v_order_number text;
  v_subtotal numeric := 0;
  v_delivery numeric := 0;
  v_payment_fee numeric := 0;
  v_total numeric := 0;
  v_payment public.payment_methods%rowtype;
  v_method public.shipping_methods%rowtype;
  v_method_zone public.shipping_method_zones%rowtype;
  v_zone_extra numeric := 0;
  v_free_over numeric := null;
  v_customer_name text;
  v_customer_email text;
  v_payment_transaction_code text;
  v_line record;
  v_unit_price numeric;
  v_new_stock integer;
begin
  create temp table if not exists checkout_order_items (
    product_id uuid primary key,
    quantity integer not null
  ) on commit drop;

  truncate table checkout_order_items;

  if v_user_id is not null then
    select id into v_cart_id
    from public.carts
    where user_id = v_user_id
    limit 1;
  end if;

  if v_cart_id is not null and exists (select 1 from public.cart_items where cart_id = v_cart_id) then
    insert into checkout_order_items (product_id, quantity)
    select product_id, sum(quantity)::integer
    from public.cart_items
    where cart_id = v_cart_id
    group by product_id;
  else
    insert into checkout_order_items (product_id, quantity)
    select
      (item ->> 'product_id')::uuid,
      sum(greatest(1, coalesce((item ->> 'quantity')::integer, 1)))::integer
    from jsonb_array_elements(coalesce(p_items, '[]'::jsonb)) as item
    where item ? 'product_id'
    group by (item ->> 'product_id')::uuid;
  end if;

  if not exists (select 1 from checkout_order_items) then
    raise exception 'Your cart is empty.';
  end if;

  select * into v_payment
  from public.payment_methods
  where id = p_payment_method_id
    and is_active = true
  limit 1;

  if v_payment.id is null then
    raise exception 'Selected payment method is not available.';
  end if;

  if coalesce((v_payment.config ->> 'requires_online_payment')::boolean, false) then
    raise exception 'Selected payment method requires a payment provider integration.';
  end if;

  select * into v_method
  from public.shipping_methods
  where id = p_delivery_method_id
    and is_active = true
  limit 1;

  if v_method.id is null then
    raise exception 'Selected delivery method is not available.';
  end if;

  if p_shipping_method_zone_id is not null then
    select * into v_method_zone
    from public.shipping_method_zones
    where id = p_shipping_method_zone_id
      and shipping_method_id = p_delivery_method_id
      and is_active = true
    limit 1;

    if v_method_zone.id is null then
      raise exception 'Selected delivery zone is not available.';
    end if;

    select coalesce(extra_cost, 0) into v_zone_extra
    from public.delivery_zones
    where id = v_method_zone.delivery_zone_id
      and is_active = true;

    v_delivery := coalesce(v_method_zone.cost_override, v_method.base_cost, 0) + coalesce(v_zone_extra, 0);
    v_free_over := coalesce(v_method_zone.free_shipping_min_amount_override, v_method.free_shipping_min_amount);
  else
    v_delivery := coalesce(v_method.base_cost, 0);
    v_free_over := v_method.free_shipping_min_amount;
  end if;

  for v_line in
    select
      ci.product_id,
      ci.quantity,
      p.name,
      p.price,
      p.sale_price,
      coalesce(p.stock, 0) as stock,
      coalesce(p.sold_count, 0) as sold_count,
      coalesce(p.is_active, true) as is_active
    from checkout_order_items ci
    join public.products p on p.id = ci.product_id
    for update of p
  loop
    if v_line.quantity < 1 then
      raise exception 'Invalid quantity for %.', v_line.name;
    end if;

    if not v_line.is_active then
      raise exception '% is no longer available.', v_line.name;
    end if;

    if v_line.stock < v_line.quantity then
      raise exception 'Only % units of % are available.', v_line.stock, v_line.name;
    end if;

    v_unit_price := case
      when v_line.sale_price is not null and v_line.sale_price > 0 and v_line.sale_price < v_line.price
        then v_line.sale_price
      else v_line.price
    end;

    v_subtotal := v_subtotal + (v_unit_price * v_line.quantity);
  end loop;

  if v_free_over is not null and v_subtotal >= v_free_over then
    v_delivery := 0;
  end if;

  if v_payment.min_amount is not null and (v_subtotal + v_delivery) < v_payment.min_amount then
    raise exception 'Selected payment method minimum amount is not met.';
  end if;

  if v_payment.max_amount is not null and (v_subtotal + v_delivery) > v_payment.max_amount then
    raise exception 'Selected payment method maximum amount is exceeded.';
  end if;

  v_payment_fee := coalesce(v_payment.fee_fixed, 0) + ((v_subtotal + v_delivery) * coalesce(v_payment.fee_percentage, 0) / 100);
  v_total := round(v_subtotal + v_delivery + v_payment_fee, 2);

  if p_expected_total is not null and abs(v_total - round(p_expected_total, 2)) > 0.01 then
    raise exception 'Order total changed. Please review your checkout summary.';
  end if;

  v_order_number := 'ORD-' || to_char(now(), 'YYYYMMDD') || '-' || upper(substr(replace(extensions.uuid_generate_v4()::text, '-', ''), 1, 6));
  v_customer_name := trim(coalesce(p_shipping ->> 'firstName', '') || ' ' || coalesce(p_shipping ->> 'lastName', ''));
  v_customer_email := nullif(p_shipping ->> 'email', '');

  insert into public.orders (
    user_id,
    order_number,
    status,
    payment_status,
    subtotal,
    shipping,
    total,
    address,
    city,
    country,
    phone,
    notes
  )
  values (
    v_user_id,
    v_order_number,
    'processing',
    'unpaid',
    round(v_subtotal, 2),
    round(v_delivery, 2),
    v_total,
    nullif(p_shipping ->> 'address', ''),
    nullif(p_shipping ->> 'city', ''),
    nullif(p_shipping ->> 'country', ''),
    nullif(p_shipping ->> 'phone', ''),
    concat_ws(
      E'\n',
      'State/Province: ' || nullif(p_shipping ->> 'state', ''),
      'Postal Code: ' || nullif(p_shipping ->> 'postalCode', ''),
      'Payment fee: ' || round(v_payment_fee, 2)::text,
      'Payment reference: ' || nullif(p_payment_reference, '')
    )
  )
  returning id into v_order_id;

  for v_line in
    select
      ci.product_id,
      ci.quantity,
      p.name,
      p.price,
      p.sale_price,
      coalesce(p.stock, 0) as stock,
      coalesce(p.sold_count, 0) as sold_count
    from checkout_order_items ci
    join public.products p on p.id = ci.product_id
    for update of p
  loop
    v_unit_price := case
      when v_line.sale_price is not null and v_line.sale_price > 0 and v_line.sale_price < v_line.price
        then v_line.sale_price
      else v_line.price
    end;
    v_new_stock := v_line.stock - v_line.quantity;

    insert into public.order_items (order_id, product_id, quantity, price, total)
    values (v_order_id, v_line.product_id, v_line.quantity, v_unit_price, round(v_unit_price * v_line.quantity, 2));

    update public.products
    set stock = v_new_stock,
        sold_count = v_line.sold_count + v_line.quantity
    where id = v_line.product_id;

    if to_regclass('public.inventory_changes') is not null then
      insert into public.inventory_changes (product_id, previous_stock, new_stock, change_type, note)
      values (v_line.product_id, v_line.stock, v_new_stock, 'adjustment', 'Customer order ' || v_order_number);
    end if;
  end loop;

  v_payment_transaction_code := 'PAY-' || to_char(now(), 'YYYYMMDD') || '-' || upper(substr(replace(extensions.uuid_generate_v4()::text, '-', ''), 1, 6));

  insert into public.payment_transactions (
    order_id,
    payment_method_id,
    transaction_code,
    order_number,
    customer_name,
    customer_email,
    method_code,
    method_name,
    provider,
    amount,
    fee_amount,
    currency,
    status,
    reference,
    notes,
    config
  )
  values (
    v_order_id,
    v_payment.id,
    v_payment_transaction_code,
    v_order_number,
    nullif(v_customer_name, ''),
    v_customer_email,
    v_payment.code,
    v_payment.name,
    v_payment.provider,
    v_total,
    round(v_payment_fee, 2),
    'USD',
    'pending',
    nullif(p_payment_reference, ''),
    v_payment.instructions_en,
    jsonb_build_object('shipping_method_id', p_delivery_method_id, 'shipping_method_zone_id', p_shipping_method_zone_id)
  );

  if v_cart_id is not null then
    delete from public.cart_items where cart_id = v_cart_id;
  end if;

  order_id := v_order_id;
  order_number := v_order_number;
  payment_status := 'unpaid';
  total := v_total;
  return next;
end;

declare
  v_auth_user_id uuid := auth.uid();
  v_order_user_id uuid;
  v_cart_user_id uuid;
  v_order_id uuid;
  v_order_number text;
  v_status text := 'processing';
  v_payment_status text := 'unpaid';
  v_subtotal numeric(10,2) := 0;
  v_shipping_cost numeric(10,2) := 0;
  v_payment_fee numeric(10,2) := 0;
  v_discount_amount numeric(10,2) := 0;
  v_total numeric(10,2) := 0;
  v_shipping public.shipping_methods%rowtype;
  v_payment public.payment_methods%rowtype;
  v_line record;
  v_item jsonb;
  v_product_id_text text;
  v_quantity_text text;
  v_unit_price numeric(10,2);
  v_new_stock integer;
  v_submitted_count integer;
  v_cart_item_count integer;
  v_product_count integer;
  v_customer_name text;
  v_customer_email text;
  v_payment_transaction_code text;
begin
  if jsonb_typeof(p_items) is distinct from 'array' or jsonb_array_length(p_items) = 0 then
    raise exception 'Order items must be a non-empty JSON array.';
  end if;

  if jsonb_typeof(p_shipping_address) is distinct from 'object' then
    raise exception 'Shipping information is required.';
  end if;

  if nullif(btrim(p_shipping_address ->> 'first_name'), '') is null
    or nullif(btrim(p_shipping_address ->> 'last_name'), '') is null
    or nullif(btrim(p_shipping_address ->> 'email'), '') is null
    or nullif(btrim(p_shipping_address ->> 'street_address'), '') is null
    or nullif(btrim(p_shipping_address ->> 'city'), '') is null
    or nullif(btrim(p_shipping_address ->> 'state_province'), '') is null
    or nullif(btrim(p_shipping_address ->> 'postal_code'), '') is null
    or nullif(btrim(p_shipping_address ->> 'country'), '') is null
  then
    raise exception 'Complete shipping information is required.';
  end if;

  create temporary table checkout_submitted_items (
    product_id uuid primary key,
    quantity integer not null check (quantity > 0)
  ) on commit drop;

  for v_item in select value from jsonb_array_elements(p_items)
  loop
    if jsonb_typeof(v_item) is distinct from 'object' then
      raise exception 'Every order item must be a JSON object.';
    end if;

    v_product_id_text := v_item ->> 'product_id';
    v_quantity_text := v_item ->> 'quantity';

    if v_product_id_text is null
      or v_product_id_text !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    then
      raise exception 'Every order item must contain a valid product ID.';
    end if;

    if v_quantity_text is null or v_quantity_text !~ '^[1-9][0-9]*$' then
      raise exception 'Every order quantity must be a positive integer.';
    end if;

    begin
      insert into checkout_submitted_items (product_id, quantity)
      values (v_product_id_text::uuid, v_quantity_text::integer);
    exception
      when unique_violation then
        raise exception 'Duplicate product IDs are not allowed.';
      when numeric_value_out_of_range then
        raise exception 'Order quantity is too large.';
    end;
  end loop;

  select count(*) into v_submitted_count from checkout_submitted_items;

  if p_cart_id is not null then
    select user_id
    into v_cart_user_id
    from public.carts
    where id = p_cart_id
    for update;

    if not found then
      raise exception 'The requested cart does not exist.';
    end if;

    if v_cart_user_id is not null
      and (v_auth_user_id is null or v_cart_user_id <> v_auth_user_id)
    then
      raise exception 'You do not have access to this cart.';
    end if;

    select count(*)
    into v_cart_item_count
    from public.cart_items
    where cart_id = p_cart_id;

    if v_cart_item_count <> v_submitted_count or exists (
      select 1
      from checkout_submitted_items submitted
      full join (
        select product_id, quantity
        from public.cart_items
        where cart_id = p_cart_id
      ) cart_item on cart_item.product_id = submitted.product_id
      where submitted.product_id is null
         or cart_item.product_id is null
         or submitted.quantity <> cart_item.quantity
    ) then
      raise exception 'Submitted items do not match the current cart.';
    end if;
  end if;

  select id
  into v_order_user_id
  from public.profiles
  where id = v_auth_user_id
  limit 1;

  select *
  into v_shipping
  from public.shipping_methods
  where id = p_shipping_method_id
    and is_active = true
  limit 1;

  if v_shipping.id is null then
    raise exception 'Selected shipping method is not available.';
  end if;

  select *
  into v_payment
  from public.payment_methods
  where id = p_payment_method_id
    and is_active = true
  limit 1;

  if v_payment.id is null then
    raise exception 'Selected payment method is not available.';
  end if;

  if coalesce((v_payment.config ->> 'requires_online_payment')::boolean, false) then
    raise exception 'Selected payment method requires a payment provider integration.';
  end if;

  select count(*)
  into v_product_count
  from public.products product
  join checkout_submitted_items submitted on submitted.product_id = product.id;

  if v_product_count <> v_submitted_count then
    raise exception 'One or more products no longer exist.';
  end if;

  for v_line in
    select
      product.id,
      product.name,
      product.price,
      product.sale_price,
      coalesce(product.stock, 0) as stock,
      coalesce(product.sold_count, 0) as sold_count,
      product.is_active is true as is_active,
      submitted.quantity
    from checkout_submitted_items submitted
    join public.products product on product.id = submitted.product_id
    order by product.id
    for update of product
  loop
    if not v_line.is_active then
      raise exception '% is no longer available.', v_line.name;
    end if;

    if v_line.price is null or v_line.price <= 0 then
      raise exception '% has an invalid price.', v_line.name;
    end if;

    if v_line.sale_price is not null and v_line.sale_price < 0 then
      raise exception '% has an invalid sale price.', v_line.name;
    end if;

    if v_line.stock < v_line.quantity then
      raise exception 'Only % units of % are available.', v_line.stock, v_line.name;
    end if;

    v_unit_price := case
      when v_line.sale_price is not null
        and v_line.sale_price > 0
        and v_line.sale_price < v_line.price
      then v_line.sale_price
      else v_line.price
    end;

    v_subtotal := v_subtotal + round(v_unit_price * v_line.quantity, 2);
  end loop;

  v_shipping_cost := coalesce(v_shipping.base_cost, 0);
  if v_shipping.free_shipping_min_amount is not null
    and v_subtotal >= v_shipping.free_shipping_min_amount
  then
    v_shipping_cost := 0;
  end if;

  if v_shipping_cost < 0 then
    raise exception 'Selected shipping method has an invalid cost.';
  end if;

  if v_payment.min_amount is not null
    and (v_subtotal + v_shipping_cost) < v_payment.min_amount
  then
    raise exception 'Selected payment method minimum amount is not met.';
  end if;

  if v_payment.max_amount is not null
    and (v_subtotal + v_shipping_cost) > v_payment.max_amount
  then
    raise exception 'Selected payment method maximum amount is exceeded.';
  end if;

  v_payment_fee := round(
    coalesce(v_payment.fee_fixed, 0)
      + ((v_subtotal + v_shipping_cost) * coalesce(v_payment.fee_percentage, 0) / 100),
    2
  );

  if v_payment_fee < 0 then
    raise exception 'Selected payment method has an invalid fee.';
  end if;

  v_subtotal := round(v_subtotal, 2);
  v_shipping_cost := round(v_shipping_cost, 2);
  v_total := round(v_subtotal + v_shipping_cost + v_payment_fee - v_discount_amount, 2);
  v_order_number := 'ORD-' || to_char(clock_timestamp(), 'YYYYMMDD') || '-'
    || upper(substr(replace(extensions.uuid_generate_v4()::text, '-', ''), 1, 6));

  insert into public.orders (
    user_id,
    cart_id,
    shipping_method_id,
    payment_method_id,
    order_number,
    status,
    payment_status,
    subtotal,
    shipping,
    payment_fee,
    discount_amount,
    total,
    address,
    city,
    country,
    phone,
    notes
  )
  values (
    v_order_user_id,
    p_cart_id,
    v_shipping.id,
    v_payment.id,
    v_order_number,
    v_status,
    v_payment_status,
    v_subtotal,
    v_shipping_cost,
    v_payment_fee,
    v_discount_amount,
    v_total,
    btrim(p_shipping_address ->> 'street_address'),
    btrim(p_shipping_address ->> 'city'),
    btrim(p_shipping_address ->> 'country'),
    nullif(btrim(p_shipping_address ->> 'phone'), ''),
    nullif(btrim(p_customer_notes), '')
  )
  returning id into v_order_id;

  insert into public.order_shipping_addresses (
    order_id,
    first_name,
    last_name,
    email,
    phone,
    street_address,
    address_line_2,
    city,
    state_province,
    postal_code,
    country,
    delivery_instructions
  )
  values (
    v_order_id,
    btrim(p_shipping_address ->> 'first_name'),
    btrim(p_shipping_address ->> 'last_name'),
    btrim(p_shipping_address ->> 'email'),
    nullif(btrim(p_shipping_address ->> 'phone'), ''),
    btrim(p_shipping_address ->> 'street_address'),
    nullif(btrim(p_shipping_address ->> 'address_line_2'), ''),
    btrim(p_shipping_address ->> 'city'),
    btrim(p_shipping_address ->> 'state_province'),
    btrim(p_shipping_address ->> 'postal_code'),
    btrim(p_shipping_address ->> 'country'),
    nullif(btrim(p_shipping_address ->> 'delivery_instructions'), '')
  );

  for v_line in
    select
      product.id,
      product.name,
      product.price,
      product.sale_price,
      coalesce(product.stock, 0) as stock,
      coalesce(product.sold_count, 0) as sold_count,
      submitted.quantity
    from checkout_submitted_items submitted
    join public.products product on product.id = submitted.product_id
    order by product.id
    for update of product
  loop
    v_unit_price := case
      when v_line.sale_price is not null
        and v_line.sale_price > 0
        and v_line.sale_price < v_line.price
      then v_line.sale_price
      else v_line.price
    end;
    v_new_stock := v_line.stock - v_line.quantity;

    insert into public.order_items (order_id, product_id, quantity, price, total)
    values (
      v_order_id,
      v_line.id,
      v_line.quantity,
      v_unit_price,
      round(v_unit_price * v_line.quantity, 2)
    );

    update public.products
    set stock = v_new_stock,
        sold_count = v_line.sold_count + v_line.quantity
    where id = v_line.id;

    insert into public.inventory_logs (
      product_id,
      previous_stock,
      new_stock,
      change_type,
      note
    )
    values (
      v_line.id,
      v_line.stock,
      v_new_stock,
      'adjustment',
      'Customer order ' || v_order_number
    );
  end loop;

  v_customer_name := btrim(
    (p_shipping_address ->> 'first_name') || ' ' || (p_shipping_address ->> 'last_name')
  );
  v_customer_email := btrim(p_shipping_address ->> 'email');
  v_payment_transaction_code := 'PAY-' || to_char(clock_timestamp(), 'YYYYMMDD') || '-'
    || upper(substr(replace(extensions.uuid_generate_v4()::text, '-', ''), 1, 6));

  insert into public.payment_transactions (
    order_id,
    payment_method_id,
    transaction_code,
    order_number,
    customer_name,
    customer_email,
    method_code,
    method_name,
    provider,
    amount,
    fee_amount,
    currency,
    status,
    notes,
    config
  )
  values (
    v_order_id,
    v_payment.id,
    v_payment_transaction_code,
    v_order_number,
    v_customer_name,
    v_customer_email,
    v_payment.code,
    v_payment.name,
    v_payment.provider,
    v_total,
    v_payment_fee,
    'USD',
    'pending',
    v_payment.instructions_en,
    jsonb_build_object('shipping_method_id', v_shipping.id)
  );

  if p_cart_id is not null then
    delete from public.cart_items where cart_id = p_cart_id;
  end if;

  return jsonb_build_object(
    'order_id', v_order_id,
    'order_number', v_order_number,
    'status', v_status,
    'payment_status', v_payment_status,
    'subtotal', v_subtotal,
    'shipping_cost', v_shipping_cost,
    'payment_fee', v_payment_fee,
    'discount_amount', v_discount_amount,
    'total', v_total
  );
end;

declare
  customer_role_id uuid;
  provisioned_role text;
begin
  -- raw_app_meta_data can only be assigned by the trusted Admin API/service role.
  -- Public signUp callers can modify raw_user_meta_data, so it is never trusted here.
  provisioned_role := lower(coalesce(new.raw_app_meta_data ->> 'role', ''));
  if provisioned_role in ('admin', 'super_admin', 'staff') then
    return new;
  end if;

  select id into customer_role_id
  from public.roles
  where name = 'customer'
  limit 1;

  if customer_role_id is null then
    raise exception using
      errcode = 'P0001',
      message = 'Customer role is not configured.';
  end if;

  insert into public.profiles (
    id,
    role_id,
    full_name,
    email,
    phone,
    is_active
  ) values (
    new.id,
    customer_role_id,
    nullif(trim(coalesce(new.raw_user_meta_data ->> 'full_name', '')), ''),
    new.email,
    nullif(trim(coalesce(new.raw_user_meta_data ->> 'phone', '')), ''),
    true
  )
  on conflict (id) do nothing;

  return new;
end;

declare
  old_role_name text;
begin
  select name into old_role_name from public.roles where id = old.role_id;

  if old_role_name = 'customer' and auth.role() <> 'service_role' then
    new.role_id := old.role_id;
    new.is_active := old.is_active;
    new.email := old.email;
  end if;

  return new;
end;

declare
  v_auth_user_id uuid := auth.uid();
  v_discount public.discounts%rowtype;
  v_result jsonb;
  v_order_id uuid;
  v_subtotal numeric(10,2);
  v_shipping_cost numeric(10,2);
  v_payment_fee numeric(10,2);
  v_eligible_subtotal numeric(10,2) := 0;
  v_discount_amount numeric(10,2) := 0;
  v_total numeric(10,2);
  v_customer_usage integer := 0;
begin
  if (p_discount_id is null) <> (nullif(btrim(p_discount_code), '') is null) then
    raise exception 'The applied promo information is incomplete. Remove it or apply it again.';
  end if;

  if p_discount_id is not null then
    select *
    into v_discount
    from public.discounts
    where id = p_discount_id
    for update;

    if not found then
      raise exception 'The applied promo code no longer exists.';
    end if;

    if upper(btrim(v_discount.code)) <> upper(btrim(p_discount_code)) then
      raise exception 'The applied promo code is invalid. Remove it or apply it again.';
    end if;

    if v_discount.is_active is distinct from true then
      raise exception 'The applied promo code is no longer active.';
    end if;

    if v_discount.start_date is not null and now() < v_discount.start_date then
      raise exception 'The applied promo code is not active yet.';
    end if;

    if v_discount.end_date is not null and now() > v_discount.end_date then
      raise exception 'The applied promo code has expired.';
    end if;

    if v_discount.usage_limit is not null
      and coalesce(v_discount.usage_count, 0) >= v_discount.usage_limit
    then
      raise exception 'The applied promo code has reached its usage limit.';
    end if;

    if v_discount.discount_type is null
      or v_discount.discount_type not in ('percentage', 'fixed_amount')
    then
      raise exception 'The applied promo code cannot be used as an order discount.';
    end if;

    if v_discount.applies_to is null
      or v_discount.applies_to not in ('all', 'product', 'category')
    then
      raise exception 'The applied promo code has an unsupported eligibility rule.';
    end if;

    if v_discount.discount_value is null or v_discount.discount_value <= 0 then
      raise exception 'The applied promo code has an invalid discount value.';
    end if;

    if v_discount.discount_type = 'percentage' and v_discount.discount_value > 100 then
      raise exception 'The applied promo code has an invalid percentage.';
    end if;
  end if;

  v_result := public.place_customer_order(
    p_cart_id,
    p_shipping_method_id,
    p_payment_method_id,
    p_shipping_address,
    p_items,
    p_customer_notes
  );

  v_order_id := (v_result ->> 'order_id')::uuid;
  v_subtotal := (v_result ->> 'subtotal')::numeric;
  v_shipping_cost := (v_result ->> 'shipping_cost')::numeric;
  v_payment_fee := (v_result ->> 'payment_fee')::numeric;

  if p_discount_id is not null then
    if v_subtotal < coalesce(v_discount.minimum_order_amount, 0) then
      raise exception 'The order no longer meets the promo code minimum amount.';
    end if;

    if v_auth_user_id is not null and v_discount.usage_per_customer is not null then
      select count(*)
      into v_customer_usage
      from public.orders
      where user_id = v_auth_user_id
        and discount_id = v_discount.id;

      if v_customer_usage >= v_discount.usage_per_customer then
        raise exception 'You have already used this promo code the maximum number of times.';
      end if;
    end if;

    if v_discount.applies_to = 'all' then
      select coalesce(sum(item.total), 0)
      into v_eligible_subtotal
      from public.order_items item
      where item.order_id = v_order_id;
    elsif v_discount.applies_to = 'product' then
      if v_discount.product_id is null then
        raise exception 'The applied promo code has no eligible product.';
      end if;

      select coalesce(sum(item.total), 0)
      into v_eligible_subtotal
      from public.order_items item
      where item.order_id = v_order_id
        and item.product_id = v_discount.product_id;
    else
      if v_discount.category_id is null then
        raise exception 'The applied promo code has no eligible category.';
      end if;

      select coalesce(sum(item.total), 0)
      into v_eligible_subtotal
      from public.order_items item
      join public.products product on product.id = item.product_id
      where item.order_id = v_order_id
        and product.category_id = v_discount.category_id;
    end if;

    v_eligible_subtotal := round(v_eligible_subtotal, 2);
    if v_eligible_subtotal <= 0 then
      raise exception 'The applied promo code is not valid for the products in this order.';
    end if;

    if v_discount.discount_type = 'percentage' then
      v_discount_amount := round(
        v_eligible_subtotal * v_discount.discount_value / 100,
        2
      );
    else
      v_discount_amount := round(v_discount.discount_value, 2);
    end if;

    v_discount_amount := least(v_eligible_subtotal, greatest(0, v_discount_amount));
  end if;

  v_total := greatest(
    0,
    round(v_subtotal + v_shipping_cost + v_payment_fee - v_discount_amount, 2)
  );

  update public.orders
  set discount_id = case when p_discount_id is null then null else v_discount.id end,
      discount_code = case when p_discount_id is null then null else v_discount.code end,
      discount_amount = v_discount_amount,
      total = v_total
  where id = v_order_id;

  update public.payment_transactions
  set amount = v_total
  where order_id = v_order_id;

  if p_discount_id is not null then
    update public.discounts
    set usage_count = coalesce(usage_count, 0) + 1,
        updated_at = now()
    where id = v_discount.id;
  end if;

  return v_result || jsonb_build_object(
    'discount_id', case when p_discount_id is null then null else v_discount.id end,
    'discount_code', case when p_discount_id is null then null else v_discount.code end,
    'discount_amount', v_discount_amount,
    'total', v_total
  );
end;

declare
  v_result jsonb;
  v_order_id uuid;
  v_shipping public.shipping_methods%rowtype;
  v_payment public.payment_methods%rowtype;
  v_discount public.discounts%rowtype;
  v_subtotal numeric(10,2) := 0;
  v_shipping_cost numeric(10,2) := 0;
  v_payment_fee numeric(10,2) := 0;
  v_eligible_subtotal numeric(10,2) := 0;
  v_discount_amount numeric(10,2) := 0;
  v_total numeric(10,2) := 0;
begin
  v_result := public.place_customer_order_legacy_discount(
    p_cart_id,
    p_shipping_method_id,
    p_payment_method_id,
    p_shipping_address,
    p_items,
    p_customer_notes,
    p_discount_id,
    p_discount_code
  );

  v_order_id := (v_result ->> 'order_id')::uuid;

  update public.order_items item
  set price = case
        when product.sale_price is not null
          and product.sale_price > 0
          and product.sale_price < product.price
        then product.sale_price
        else product.price
      end,
      total = round(
        (case
          when product.sale_price is not null
            and product.sale_price > 0
            and product.sale_price < product.price
          then product.sale_price
          else product.price
        end) * item.quantity,
        2
      )
  from public.products product
  where item.order_id = v_order_id
    and product.id = item.product_id;

  select coalesce(sum(item.total), 0)
  into v_subtotal
  from public.order_items item
  where item.order_id = v_order_id;

  v_subtotal := round(v_subtotal, 2);
  if v_subtotal <= 0 then
    raise exception 'The order has no valid priced items.';
  end if;

  if p_expected_subtotal is null or p_expected_subtotal < 0 then
    raise exception 'The expected order subtotal is invalid.';
  end if;

  if abs(v_subtotal - round(p_expected_subtotal, 2)) > 0.01 then
    raise exception 'Order pricing changed. Please review your cart before placing the order.';
  end if;

  select *
  into v_shipping
  from public.shipping_methods
  where id = p_shipping_method_id
    and is_active = true;

  if not found then
    raise exception 'Selected shipping method is not available.';
  end if;

  v_shipping_cost := coalesce(v_shipping.base_cost, 0);
  if v_shipping.free_shipping_min_amount is not null
    and v_subtotal >= v_shipping.free_shipping_min_amount
  then
    v_shipping_cost := 0;
  end if;
  v_shipping_cost := round(v_shipping_cost, 2);

  if v_shipping_cost < 0 then
    raise exception 'Selected shipping method has an invalid cost.';
  end if;

  select *
  into v_payment
  from public.payment_methods
  where id = p_payment_method_id
    and is_active = true;

  if not found then
    raise exception 'Selected payment method is not available.';
  end if;

  if v_payment.min_amount is not null
    and (v_subtotal + v_shipping_cost) < v_payment.min_amount
  then
    raise exception 'Selected payment method minimum amount is not met.';
  end if;

  if v_payment.max_amount is not null
    and (v_subtotal + v_shipping_cost) > v_payment.max_amount
  then
    raise exception 'Selected payment method maximum amount is exceeded.';
  end if;

  v_payment_fee := round(
    coalesce(v_payment.fee_fixed, 0)
      + ((v_subtotal + v_shipping_cost) * coalesce(v_payment.fee_percentage, 0) / 100),
    2
  );

  if v_payment_fee < 0 then
    raise exception 'Selected payment method has an invalid fee.';
  end if;

  if p_discount_id is not null then
    select *
    into v_discount
    from public.discounts
    where id = p_discount_id;

    if not found then
      raise exception 'The applied promo code no longer exists.';
    end if;

    if v_subtotal < coalesce(v_discount.minimum_order_amount, 0) then
      raise exception 'The order no longer meets the promo code minimum amount.';
    end if;

    if v_discount.applies_to = 'all' then
      select coalesce(sum(item.total), 0)
      into v_eligible_subtotal
      from public.order_items item
      where item.order_id = v_order_id;
    elsif v_discount.applies_to = 'product' then
      select coalesce(sum(item.total), 0)
      into v_eligible_subtotal
      from public.order_items item
      where item.order_id = v_order_id
        and item.product_id = v_discount.product_id;
    elsif v_discount.applies_to = 'category' then
      select coalesce(sum(item.total), 0)
      into v_eligible_subtotal
      from public.order_items item
      join public.products product on product.id = item.product_id
      where item.order_id = v_order_id
        and product.category_id = v_discount.category_id;
    else
      raise exception 'The applied promo code has an unsupported eligibility rule.';
    end if;

    v_eligible_subtotal := round(v_eligible_subtotal, 2);
    if v_eligible_subtotal <= 0 then
      raise exception 'The applied promo code is not valid for the products in this order.';
    end if;

    if v_discount.discount_type = 'percentage' then
      v_discount_amount := round(
        v_eligible_subtotal * v_discount.discount_value / 100,
        2
      );
    elsif v_discount.discount_type = 'fixed_amount' then
      v_discount_amount := round(v_discount.discount_value, 2);
    else
      raise exception 'The applied promo code cannot be used as an order discount.';
    end if;

    v_discount_amount := least(
      v_eligible_subtotal,
      greatest(0, v_discount_amount)
    );
  end if;

  v_total := greatest(
    0,
    round(v_subtotal + v_shipping_cost + v_payment_fee - v_discount_amount, 2)
  );

  update public.orders
  set subtotal = v_subtotal,
      shipping = v_shipping_cost,
      payment_fee = v_payment_fee,
      discount_amount = v_discount_amount,
      total = v_total
  where id = v_order_id;

  update public.payment_transactions
  set amount = v_total,
      fee_amount = v_payment_fee
  where order_id = v_order_id;

  return v_result || jsonb_build_object(
    'subtotal', v_subtotal,
    'shipping_cost', v_shipping_cost,
    'payment_fee', v_payment_fee,
    'discount_amount', v_discount_amount,
    'total', v_total
  );
end;

declare
  v_result jsonb;
  v_existing_result jsonb;
begin
  if p_checkout_token is null then
    raise exception 'A checkout idempotency token is required.';
  end if;

  if nullif(btrim(p_shipping_address ->> 'email'), '') is null then
    raise exception 'A shipping email is required.';
  end if;

  select jsonb_build_object(
    'order_id', orders.id,
    'order_number', orders.order_number,
    'status', orders.status,
    'payment_status', orders.payment_status,
    'subtotal', orders.subtotal,
    'shipping_cost', orders.shipping,
    'payment_fee', orders.payment_fee,
    'discount_id', orders.discount_id,
    'discount_code', orders.discount_code,
    'discount_amount', orders.discount_amount,
    'total', orders.total
  )
  into v_existing_result
  from public.orders
  join public.order_shipping_addresses address on address.order_id = orders.id
  where orders.checkout_token = p_checkout_token
    and (
      (auth.uid() is not null and orders.user_id = auth.uid())
      or (
        auth.uid() is null
        and orders.user_id is null
        and lower(address.email) = lower(btrim(p_shipping_address ->> 'email'))
      )
    );

  if v_existing_result is not null then
    return v_existing_result;
  end if;

  begin
    v_result := public.place_customer_order(
      p_cart_id,
      p_shipping_method_id,
      p_payment_method_id,
      p_shipping_address,
      p_items,
      p_customer_notes,
      p_discount_id,
      p_discount_code,
      p_expected_subtotal
    );

    update public.orders
    set checkout_token = p_checkout_token
    where id = (v_result ->> 'order_id')::uuid;

    if not found then
      raise exception 'The created order could not be assigned its checkout token.';
    end if;

    return v_result;
  exception
    when unique_violation then
      select jsonb_build_object(
        'order_id', orders.id,
        'order_number', orders.order_number,
        'status', orders.status,
        'payment_status', orders.payment_status,
        'subtotal', orders.subtotal,
        'shipping_cost', orders.shipping,
        'payment_fee', orders.payment_fee,
        'discount_id', orders.discount_id,
        'discount_code', orders.discount_code,
        'discount_amount', orders.discount_amount,
        'total', orders.total
      )
      into v_existing_result
      from public.orders
      join public.order_shipping_addresses address on address.order_id = orders.id
      where orders.checkout_token = p_checkout_token
        and (
          (auth.uid() is not null and orders.user_id = auth.uid())
          or (
            auth.uid() is null
            and orders.user_id is null
            and lower(address.email) = lower(btrim(p_shipping_address ->> 'email'))
          )
        );

      if v_existing_result is null then
        raise;
      end if;

      return v_existing_result;
  end;
end;

declare
  v_previous_stock integer;
begin
  if p_new_stock is null or p_new_stock < 0 then
    raise exception 'Stock must be a non-negative integer.';
  end if;

  if p_change_type not in ('restock', 'adjustment', 'damage', 'return', 'correction') then
    raise exception 'Invalid inventory change type.';
  end if;

  select coalesce(stock, 0)
  into v_previous_stock
  from public.products
  where id = p_product_id
  for update;

  if not found then
    raise exception 'Product not found.';
  end if;

  update public.products
  set stock = p_new_stock
  where id = p_product_id;

  insert into public.inventory_logs (
    product_id,
    previous_stock,
    new_stock,
    change_type,
    note
  )
  values (
    p_product_id,
    v_previous_stock,
    p_new_stock,
    p_change_type,
    nullif(btrim(p_note), '')
  );
end;

declare
  current_user_id uuid := auth.uid();
begin
  if current_user_id is null then
    raise exception 'Authenticated customer session is required';
  end if;

  insert into public.customer_product_history (
    user_id,
    product_id,
    viewed_at,
    view_count
  )
  values (
    current_user_id,
    target_product_id,
    now(),
    1
  )
  on conflict (user_id, product_id)
  do update set
    viewed_at = excluded.viewed_at,
    view_count = customer_product_history.view_count + 1;
end;

begin
  raise exception 'Loyalty ledger entries are immutable.';
end;

declare
  v_balance integer;
  v_new_balance integer;
begin
  if p_transaction_type not in ('earn', 'redeem', 'earn_reversal', 'redemption_refund', 'adjustment') then
    raise exception 'Invalid loyalty ledger entry type.';
  end if;

  if p_points_delta is null or p_points_delta = 0 then
    raise exception 'Loyalty points change must be non-zero.';
  end if;

  insert into public.customer_loyalty_points_balances (user_id, balance)
  values (
    p_user_id,
    coalesce((select sum(points_delta)::integer
      from public.customer_loyalty_points_ledger where user_id = p_user_id), 0)
  )
  on conflict (user_id) do nothing;

  select balance
  into v_balance
  from public.customer_loyalty_points_balances
  where user_id = p_user_id
  for update;

  if not found then
    raise exception 'Customer profile not found.';
  end if;

  v_new_balance := v_balance + p_points_delta;
  if p_transaction_type = 'redeem' and v_new_balance < 0 then
    raise exception 'Insufficient loyalty points.';
  end if;

  insert into public.customer_loyalty_points_ledger (
    user_id, order_id, order_item_id, transaction_type, points_delta, balance_after, note
  ) values (
    p_user_id, p_order_id, p_order_item_id, p_transaction_type,
    p_points_delta, v_new_balance, nullif(btrim(p_note), '')
  );

  update public.customer_loyalty_points_balances
  set balance = v_new_balance,
      updated_at = now()
  where user_id = p_user_id;

  return v_new_balance;
end;

declare
  v_was_completed boolean := lower(coalesce(old.status, '')) in ('delivered', 'completed');
  v_is_completed boolean := lower(coalesce(new.status, '')) in ('delivered', 'completed');
  v_was_refunded boolean := lower(coalesce(old.status, '')) in ('cancelled', 'canceled', 'refunded', 'returned')
    or lower(coalesce(old.payment_status, '')) = 'refunded';
  v_is_refunded boolean := lower(coalesce(new.status, '')) in ('cancelled', 'canceled', 'refunded', 'returned')
    or lower(coalesce(new.payment_status, '')) = 'refunded';
begin
  if new.user_id is null then
    return new;
  end if;

  if v_is_completed and not v_was_completed and new.loyalty_points_earned > 0
    and not exists (
      select 1 from public.customer_loyalty_points_ledger
      where user_id = new.user_id and order_id = new.id and transaction_type = 'earn'
    )
  then
    perform public.append_customer_loyalty_ledger_entry(
      new.user_id, new.id, null, 'earn', new.loyalty_points_earned,
      'Points earned for completed order ' || coalesce(new.order_number, new.id::text)
    );
  end if;

  if v_is_refunded and not v_was_refunded then
    if new.loyalty_points_redeemed > 0 and not exists (
      select 1 from public.customer_loyalty_points_ledger
      where user_id = new.user_id and order_id = new.id and transaction_type = 'redemption_refund'
    ) then
      perform public.append_customer_loyalty_ledger_entry(
        new.user_id, new.id, null, 'redemption_refund', new.loyalty_points_redeemed,
        'Redeemed points restored for cancelled or refunded order ' || coalesce(new.order_number, new.id::text)
      );
    end if;

    if exists (
      select 1 from public.customer_loyalty_points_ledger
      where user_id = new.user_id and order_id = new.id and transaction_type = 'earn'
    ) and not exists (
      select 1 from public.customer_loyalty_points_ledger
      where user_id = new.user_id and order_id = new.id and transaction_type = 'earn_reversal'
    ) then
      perform public.append_customer_loyalty_ledger_entry(
        new.user_id, new.id, null, 'earn_reversal', -new.loyalty_points_earned,
        'Earned points reversed for cancelled or refunded order ' || coalesce(new.order_number, new.id::text)
      );
    end if;
  end if;

  return new;
end;

select coalesce(
    (select sum(points_delta)::integer
      from public.customer_loyalty_points_ledger
      where user_id = auth.uid()),
    0
  );

declare
  v_user_id uuid := auth.uid();
  v_settings public.loyalty_program_settings%rowtype;
  v_result jsonb;
  v_order_id uuid;
  v_product_id uuid;
  v_product public.products%rowtype;
  v_quantity integer;
  v_points_cost integer;
  v_total_points_cost integer := 0;
  v_subtotal numeric(10,2);
  v_discount_amount numeric(10,2);
  v_shipping public.shipping_methods%rowtype;
  v_payment public.payment_methods%rowtype;
  v_shipping_cost numeric(10,2);
  v_payment_fee numeric(10,2);
  v_total numeric(10,2);
  v_points_earned integer := 0;
  v_already_processed boolean;
  v_customer_balance integer;
begin
  if coalesce(cardinality(p_redeem_product_ids), 0) <> coalesce(
    (select count(distinct requested_id) from unnest(p_redeem_product_ids) requested_id),
    0
  ) then
    raise exception 'Duplicate loyalty redemption products are not allowed.';
  end if;

  select * into v_settings
  from public.loyalty_program_settings
  where id = true;

  if not found then
    raise exception 'Loyalty settings are unavailable.';
  end if;

  if coalesce(cardinality(p_redeem_product_ids), 0) > 0 then
    if v_user_id is null then
      raise exception 'Sign in to redeem loyalty points.';
    end if;
    if not v_settings.is_enabled then
      raise exception 'The loyalty program is currently disabled.';
    end if;
    if p_discount_id is not null then
      raise exception 'Loyalty redemption cannot be combined with a promo code.';
    end if;

    perform 1 from public.profiles where id = v_user_id;
    if not found then
      raise exception 'Customer profile not found.';
    end if;

    insert into public.customer_loyalty_points_balances (user_id, balance)
    values (
      v_user_id,
      coalesce((select sum(points_delta)::integer
        from public.customer_loyalty_points_ledger where user_id = v_user_id), 0)
    )
    on conflict (user_id) do nothing;

    select balance into v_customer_balance
    from public.customer_loyalty_points_balances
    where user_id = v_user_id
    for update;

    select jsonb_build_object(
      'order_id', orders.id,
      'order_number', orders.order_number,
      'status', orders.status,
      'payment_status', orders.payment_status,
      'subtotal', orders.subtotal,
      'shipping_cost', orders.shipping,
      'payment_fee', orders.payment_fee,
      'discount_id', orders.discount_id,
      'discount_code', orders.discount_code,
      'discount_amount', orders.discount_amount,
      'total', orders.total,
      'loyalty_points_redeemed', orders.loyalty_points_redeemed,
      'loyalty_points_earned', orders.loyalty_points_earned
    )
    into v_result
    from public.orders
    where orders.checkout_token = p_checkout_token
      and orders.user_id = v_user_id
      and orders.loyalty_checkout_processed = true;

    if v_result is not null then
      return v_result;
    end if;

    foreach v_product_id in array p_redeem_product_ids loop
      select * into v_product from public.products where id = v_product_id for update;
      if not found or v_product.is_active is distinct from true then
        raise exception 'A loyalty redemption product is unavailable.';
      end if;
      if not v_product.is_loyalty_eligible then
        raise exception 'A selected product is not eligible for loyalty redemption.';
      end if;

      select (item ->> 'quantity')::integer into v_quantity
      from jsonb_array_elements(p_items) item
      where (item ->> 'product_id')::uuid = v_product_id
      limit 1;

      if v_quantity is null or v_quantity < 1 then
        raise exception 'A loyalty redemption product is not present in the order.';
      end if;

      v_points_cost := ceil(
        ((case when v_product.sale_price is not null and v_product.sale_price > 0
          and v_product.sale_price < v_product.price then v_product.sale_price else v_product.price end)
          * v_quantity) / v_settings.point_value_usd
      );
      v_total_points_cost := v_total_points_cost + v_points_cost;
    end loop;

    if v_total_points_cost < v_settings.minimum_redemption_points then
      raise exception 'The redemption does not meet the minimum loyalty points requirement.';
    end if;
    if v_customer_balance < v_total_points_cost then
      raise exception 'Insufficient loyalty points.';
    end if;
  end if;

  v_result := public.place_customer_order(
    p_cart_id, p_shipping_method_id, p_payment_method_id, p_shipping_address,
    p_items, p_customer_notes, p_discount_id, p_discount_code,
    p_expected_subtotal, p_checkout_token
  );
  v_order_id := (v_result ->> 'order_id')::uuid;

  select loyalty_checkout_processed into v_already_processed
  from public.orders where id = v_order_id for update;
  if v_already_processed then
    return v_result || (
      select jsonb_build_object(
        'loyalty_points_redeemed', loyalty_points_redeemed,
        'loyalty_points_earned', loyalty_points_earned
      ) from public.orders where id = v_order_id
    );
  end if;

  update public.order_items item
  set loyalty_effective_unit_price = item.price,
      loyalty_redeemed = item.product_id = any(coalesce(p_redeem_product_ids, array[]::uuid[])),
      loyalty_points_cost = case
        when item.product_id = any(coalesce(p_redeem_product_ids, array[]::uuid[]))
        then ceil((item.price * item.quantity) / v_settings.point_value_usd)
        else 0
      end,
      total = case
        when item.product_id = any(coalesce(p_redeem_product_ids, array[]::uuid[])) then 0
        else item.total
      end
  where item.order_id = v_order_id;

  select round(coalesce(sum(total), 0), 2) into v_subtotal
  from public.order_items where order_id = v_order_id;
  v_discount_amount := case when v_total_points_cost > 0 then 0
    else coalesce((v_result ->> 'discount_amount')::numeric, 0) end;

  select * into v_shipping from public.shipping_methods where id = p_shipping_method_id and is_active = true;
  v_shipping_cost := coalesce(v_shipping.base_cost, 0);
  if v_shipping.free_shipping_min_amount is not null and v_subtotal >= v_shipping.free_shipping_min_amount then
    v_shipping_cost := 0;
  end if;
  v_shipping_cost := round(v_shipping_cost, 2);

  select * into v_payment from public.payment_methods where id = p_payment_method_id and is_active = true;
  v_payment_fee := round(
    coalesce(v_payment.fee_fixed, 0)
    + ((v_subtotal + v_shipping_cost) * coalesce(v_payment.fee_percentage, 0) / 100), 2
  );
  v_total := greatest(0, round(v_subtotal + v_shipping_cost + v_payment_fee - v_discount_amount, 2));

  if v_user_id is not null and v_settings.is_enabled then
    v_points_earned := floor(greatest(0, v_subtotal - v_discount_amount) * v_settings.points_earned_per_usd);
  end if;

  update public.order_items item
  set loyalty_points_earned = case when item.loyalty_redeemed then 0 else
    floor(item.total * case when v_subtotal > 0 then greatest(0, v_subtotal - v_discount_amount) / v_subtotal else 0 end
      * v_settings.points_earned_per_usd) end
  where item.order_id = v_order_id;

  update public.orders
  set subtotal = v_subtotal,
      shipping = v_shipping_cost,
      payment_fee = v_payment_fee,
      discount_amount = v_discount_amount,
      total = v_total,
      loyalty_points_redeemed = v_total_points_cost,
      loyalty_points_earned = v_points_earned,
      loyalty_point_value_usd = v_settings.point_value_usd,
      loyalty_points_earned_per_usd = v_settings.points_earned_per_usd,
      loyalty_checkout_processed = true
  where id = v_order_id;

  update public.payment_transactions
  set amount = v_total, fee_amount = v_payment_fee
  where order_id = v_order_id;

  if v_total_points_cost > 0 then
    perform public.append_customer_loyalty_ledger_entry(
      v_user_id, v_order_id, null, 'redeem', -v_total_points_cost,
      'Points redeemed for order ' || coalesce(v_result ->> 'order_number', v_order_id::text)
    );
  end if;

  return v_result || jsonb_build_object(
    'subtotal', v_subtotal,
    'shipping_cost', v_shipping_cost,
    'payment_fee', v_payment_fee,
    'discount_amount', v_discount_amount,
    'total', v_total,
    'loyalty_points_redeemed', v_total_points_cost,
    'loyalty_points_earned', v_points_earned
  );
end;

begin
  if not exists (
    select 1
    from public.profiles profile
    join public.roles role on role.id = profile.role_id
    where profile.id = auth.uid()
      and role.name in ('admin', 'super_admin')
      and profile.is_active = true
  ) then
    raise exception 'Admin access is required.';
  end if;

  if nullif(btrim(p_note), '') is null then
    raise exception 'A note is required for a loyalty points adjustment.';
  end if;

  return public.append_customer_loyalty_ledger_entry(
    p_user_id, null, null, 'adjustment', p_points_delta, p_note
  );
end;

begin
  if not exists (
    select 1
    from public.profiles profile
    join public.roles role on role.id = profile.role_id
    where profile.id = auth.uid()
      and role.name in ('admin', 'super_admin')
      and profile.is_active = true
  ) then
    raise exception 'Admin access is required.';
  end if;

  if lower(p_status) not in (
    'pending', 'processing', 'shipped', 'delivered', 'completed', 'cancelled', 'canceled', 'returned'
  ) then
    raise exception 'Unsupported order status.';
  end if;

  if lower(p_payment_status) not in ('pending', 'unpaid', 'paid', 'failed', 'refunded') then
    raise exception 'Unsupported payment status.';
  end if;

  update public.orders
  set status = lower(p_status),
      payment_status = lower(p_payment_status)
  where id = p_order_id;

  if not found then
    raise exception 'Order not found.';
  end if;
end;

declare
  v_was_completed boolean := lower(coalesce(old.status, '')) in ('delivered', 'completed');
  v_is_completed boolean := lower(coalesce(new.status, '')) in ('delivered', 'completed');
  v_was_refunded boolean := lower(coalesce(old.status, '')) in ('cancelled', 'canceled', 'refunded', 'returned')
    or lower(coalesce(old.payment_status, '')) = 'refunded';
  v_is_refunded boolean := lower(coalesce(new.status, '')) in ('cancelled', 'canceled', 'refunded', 'returned')
    or lower(coalesce(new.payment_status, '')) = 'refunded';
  v_earned_points integer := 0;
  v_awarded_points integer := 0;
begin
  if new.user_id is null then
    return new;
  end if;

  if v_is_completed and not v_was_completed then
    v_earned_points := case
      when new.loyalty_checkout_processed then new.loyalty_points_earned
      else floor(greatest(0, coalesce(new.subtotal, 0) - coalesce(new.discount_amount, 0)))::integer
    end;

    if v_earned_points > 0 and not exists (
      select 1
      from public.customer_loyalty_points_ledger
      where user_id = new.user_id
        and order_id = new.id
        and transaction_type = 'earn'
    ) then
      perform public.append_customer_loyalty_ledger_entry(
        new.user_id,
        new.id,
        null,
        'earn',
        v_earned_points,
        'Points earned for completed order ' || coalesce(new.order_number, new.id::text)
      );
    end if;
  end if;

  if v_is_refunded and not v_was_refunded then
    if new.loyalty_points_redeemed > 0 and not exists (
      select 1
      from public.customer_loyalty_points_ledger
      where user_id = new.user_id
        and order_id = new.id
        and transaction_type = 'redemption_refund'
    ) then
      perform public.append_customer_loyalty_ledger_entry(
        new.user_id,
        new.id,
        null,
        'redemption_refund',
        new.loyalty_points_redeemed,
        'Redeemed points restored for cancelled or refunded order ' || coalesce(new.order_number, new.id::text)
      );
    end if;

    select coalesce(sum(points_delta), 0)::integer
    into v_awarded_points
    from public.customer_loyalty_points_ledger
    where user_id = new.user_id
      and order_id = new.id
      and transaction_type = 'earn';

    if v_awarded_points > 0 and not exists (
      select 1
      from public.customer_loyalty_points_ledger
      where user_id = new.user_id
        and order_id = new.id
        and transaction_type = 'earn_reversal'
    ) then
      perform public.append_customer_loyalty_ledger_entry(
        new.user_id,
        new.id,
        null,
        'earn_reversal',
        -v_awarded_points,
        'Earned points reversed for cancelled or refunded order ' || coalesce(new.order_number, new.id::text)
      );
    end if;
  end if;

  return new;
end;

begin
  new.label := btrim(new.label);
  new.full_name := btrim(new.full_name);
  new.phone := btrim(new.phone);
  new.street_address := btrim(new.street_address);
  new.apartment_or_building := nullif(btrim(new.apartment_or_building), '');
  new.city := btrim(new.city);
  new.area_or_district := nullif(btrim(new.area_or_district), '');
  new.country := btrim(new.country);
  new.postal_code := nullif(btrim(new.postal_code), '');
  new.delivery_notes := nullif(btrim(new.delivery_notes), '');
  new.updated_at := now();

  if tg_op = 'INSERT' and not exists (
    select 1 from public.customer_addresses where user_id = new.user_id
  ) then
    new.is_default := true;
  end if;

  if new.is_default and (tg_op = 'INSERT' or old.is_default is distinct from true) then
    update public.customer_addresses
    set is_default = false, updated_at = now()
    where user_id = new.user_id
      and id <> new.id
      and is_default;
  end if;

  return new;
end;

begin
  if old.is_default then
    update public.customer_addresses
    set is_default = true
    where id = (
      select id
      from public.customer_addresses
      where user_id = old.user_id
      order by created_at asc, id asc
      limit 1
    );
  end if;
  return old;
end;

declare
  v_auth_user_id uuid := auth.uid();
  v_order_user_id uuid;
  v_cart_user_id uuid;
  v_order_id uuid;
  v_order_number text;
  v_status text := 'processing';
  v_payment_status text := 'unpaid';
  v_subtotal numeric(10,2) := 0;
  v_shipping_cost numeric(10,2) := 0;
  v_payment_fee numeric(10,2) := 0;
  v_total numeric(10,2) := 0;
  v_shipping public.shipping_methods%rowtype;
  v_payment public.payment_methods%rowtype;
  v_line record;
  v_unit_price numeric(10,2);
  v_regular_price numeric(10,2);
  v_sale_price numeric(10,2);
  v_previous_stock integer;
  v_new_stock integer;
  v_submitted_count integer;
  v_cart_item_count integer;
  v_customer_name text;
  v_customer_email text;
  v_payment_transaction_code text;
begin
  if not exists (
    select 1 from jsonb_array_elements(coalesce(p_items, '[]'::jsonb)) item
    where nullif(item ->> 'variant_id', '') is not null
  ) then
    return public.place_customer_order_legacy_products_only(
      p_cart_id, p_shipping_method_id, p_payment_method_id,
      p_shipping_address, p_items, p_customer_notes
    );
  end if;

  if jsonb_typeof(p_items) is distinct from 'array' or jsonb_array_length(p_items) = 0 then
    raise exception 'Order items must be a non-empty JSON array.';
  end if;
  if jsonb_typeof(p_shipping_address) is distinct from 'object' then
    raise exception 'Shipping information is required.';
  end if;
  if nullif(btrim(p_shipping_address ->> 'first_name'), '') is null
    or nullif(btrim(p_shipping_address ->> 'last_name'), '') is null
    or nullif(btrim(p_shipping_address ->> 'email'), '') is null
    or nullif(btrim(p_shipping_address ->> 'street_address'), '') is null
    or nullif(btrim(p_shipping_address ->> 'city'), '') is null
    or nullif(btrim(p_shipping_address ->> 'state_province'), '') is null
    or nullif(btrim(p_shipping_address ->> 'postal_code'), '') is null
    or nullif(btrim(p_shipping_address ->> 'country'), '') is null
  then
    raise exception 'Complete shipping information is required.';
  end if;

  create temporary table checkout_variant_items (
    product_id uuid not null,
    variant_id uuid null,
    quantity integer not null check (quantity > 0)
  ) on commit drop;
  create unique index on checkout_variant_items (
    product_id, coalesce(variant_id, '00000000-0000-0000-0000-000000000000'::uuid)
  );

  begin
    insert into checkout_variant_items(product_id, variant_id, quantity)
    select
      (item ->> 'product_id')::uuid,
      nullif(item ->> 'variant_id', '')::uuid,
      (item ->> 'quantity')::integer
    from jsonb_array_elements(p_items) item;
  exception
    when invalid_text_representation then
      raise exception 'Every order item must contain valid product and variant IDs.';
    when unique_violation then
      raise exception 'Duplicate product variants are not allowed.';
    when check_violation then
      raise exception 'Every order quantity must be a positive integer.';
  end;

  select count(*) into v_submitted_count from checkout_variant_items;

  if p_cart_id is not null then
    select user_id into v_cart_user_id from public.carts where id = p_cart_id for update;
    if not found then raise exception 'The requested cart does not exist.'; end if;
    if v_cart_user_id is not null and (v_auth_user_id is null or v_cart_user_id <> v_auth_user_id) then
      raise exception 'You do not have access to this cart.';
    end if;

    select count(*) into v_cart_item_count from public.cart_items where cart_id = p_cart_id;
    if v_cart_item_count <> v_submitted_count or exists (
      select 1
      from checkout_variant_items submitted
      full join public.cart_items cart_item
        on cart_item.cart_id = p_cart_id
       and cart_item.product_id = submitted.product_id
       and cart_item.variant_id is not distinct from submitted.variant_id
      where submitted.product_id is null or cart_item.product_id is null
         or submitted.quantity <> cart_item.quantity
    ) then
      raise exception 'Submitted items do not match the current cart.';
    end if;
  end if;

  if exists (
    select 1 from checkout_variant_items submitted
    left join public.products product on product.id = submitted.product_id
    left join public.product_variants variant
      on variant.id = submitted.variant_id and variant.product_id = submitted.product_id
    where product.id is null
      or product.is_active is distinct from true
      or (submitted.variant_id is not null and (
        variant.id is null or variant.is_active is distinct from true
      ))
  ) then
    raise exception 'One of your product selections is no longer available.';
  end if;

  perform product.id
  from public.products product
  join checkout_variant_items submitted on submitted.product_id = product.id
  order by product.id for update of product;
  perform variant.id
  from public.product_variants variant
  join checkout_variant_items submitted on submitted.variant_id = variant.id
  order by variant.id for update of variant;

  if exists (
    select 1
    from checkout_variant_items submitted
    join public.product_variants variant on variant.id = submitted.variant_id
    where variant.stock is not null and variant.stock < submitted.quantity
  ) then
    raise exception 'Insufficient stock for one of the selected variants.';
  end if;
  if exists (
    select 1
    from (
      select submitted.product_id, sum(submitted.quantity)::integer quantity
      from checkout_variant_items submitted
      left join public.product_variants variant on variant.id = submitted.variant_id
      where submitted.variant_id is null or variant.stock is null
      group by submitted.product_id
    ) fallback
    join public.products product on product.id = fallback.product_id
    where coalesce(product.stock, 0) < fallback.quantity
  ) then
    raise exception 'Insufficient stock for one of the selected products.';
  end if;

  for v_line in
    select submitted.*, product.name,
      coalesce(variant.price, product.price) regular_price,
      coalesce(variant.sale_price, product.sale_price) sale_price
    from checkout_variant_items submitted
    join public.products product on product.id = submitted.product_id
    left join public.product_variants variant on variant.id = submitted.variant_id
  loop
    v_regular_price := v_line.regular_price;
    v_sale_price := v_line.sale_price;
    if v_regular_price is null or v_regular_price <= 0 then
      raise exception '% has an invalid price.', v_line.name;
    end if;
    v_unit_price := case
      when v_sale_price is not null and v_sale_price > 0 and v_sale_price < v_regular_price
      then v_sale_price else v_regular_price end;
    v_subtotal := v_subtotal + round(v_unit_price * v_line.quantity, 2);
  end loop;
  v_subtotal := round(v_subtotal, 2);

  select * into v_shipping from public.shipping_methods
  where id = p_shipping_method_id and is_active = true;
  if not found then raise exception 'Selected shipping method is not available.'; end if;
  select * into v_payment from public.payment_methods
  where id = p_payment_method_id and is_active = true;
  if not found then raise exception 'Selected payment method is not available.'; end if;
  if coalesce((v_payment.config ->> 'requires_online_payment')::boolean, false) then
    raise exception 'Selected payment method requires a payment provider integration.';
  end if;

  v_shipping_cost := coalesce(v_shipping.base_cost, 0);
  if v_shipping.free_shipping_min_amount is not null and v_subtotal >= v_shipping.free_shipping_min_amount then
    v_shipping_cost := 0;
  end if;
  v_shipping_cost := round(v_shipping_cost, 2);
  if v_payment.min_amount is not null and v_subtotal + v_shipping_cost < v_payment.min_amount then
    raise exception 'Selected payment method minimum amount is not met.';
  end if;
  if v_payment.max_amount is not null and v_subtotal + v_shipping_cost > v_payment.max_amount then
    raise exception 'Selected payment method maximum amount is exceeded.';
  end if;
  v_payment_fee := round(coalesce(v_payment.fee_fixed, 0)
    + ((v_subtotal + v_shipping_cost) * coalesce(v_payment.fee_percentage, 0) / 100), 2);
  v_total := round(v_subtotal + v_shipping_cost + v_payment_fee, 2);

  select id into v_order_user_id from public.profiles where id = v_auth_user_id limit 1;
  v_order_number := 'ORD-' || to_char(clock_timestamp(), 'YYYYMMDD') || '-'
    || upper(substr(replace(extensions.uuid_generate_v4()::text, '-', ''), 1, 6));

  insert into public.orders (
    user_id, cart_id, shipping_method_id, payment_method_id, order_number,
    status, payment_status, subtotal, shipping, payment_fee, discount_amount,
    total, address, city, country, phone, notes
  ) values (
    v_order_user_id, p_cart_id, v_shipping.id, v_payment.id, v_order_number,
    v_status, v_payment_status, v_subtotal, v_shipping_cost, v_payment_fee, 0,
    v_total, btrim(p_shipping_address ->> 'street_address'),
    btrim(p_shipping_address ->> 'city'), btrim(p_shipping_address ->> 'country'),
    nullif(btrim(p_shipping_address ->> 'phone'), ''), nullif(btrim(p_customer_notes), '')
  ) returning id into v_order_id;

  insert into public.order_shipping_addresses (
    order_id, first_name, last_name, email, phone, street_address, address_line_2,
    city, state_province, postal_code, country, delivery_instructions
  ) values (
    v_order_id, btrim(p_shipping_address ->> 'first_name'),
    btrim(p_shipping_address ->> 'last_name'), btrim(p_shipping_address ->> 'email'),
    nullif(btrim(p_shipping_address ->> 'phone'), ''),
    btrim(p_shipping_address ->> 'street_address'),
    nullif(btrim(p_shipping_address ->> 'address_line_2'), ''),
    btrim(p_shipping_address ->> 'city'), btrim(p_shipping_address ->> 'state_province'),
    btrim(p_shipping_address ->> 'postal_code'), btrim(p_shipping_address ->> 'country'),
    nullif(btrim(p_shipping_address ->> 'delivery_instructions'), '')
  );

  for v_line in
    select submitted.*, product.name, coalesce(product.stock, 0) product_stock,
      coalesce(product.sold_count, 0) sold_count,
      coalesce(variant.price, product.price) regular_price,
      coalesce(variant.sale_price, product.sale_price) sale_price,
      variant.stock variant_stock, variant.option_name, variant.option_value,
      variant.name variant_name, variant.sku variant_sku,
      coalesce(variant.attributes, '{}'::jsonb) variant_attributes,
      variant.image_url variant_image_url
    from checkout_variant_items submitted
    join public.products product on product.id = submitted.product_id
    left join public.product_variants variant on variant.id = submitted.variant_id
    order by submitted.product_id, submitted.variant_id nulls first
  loop
    v_unit_price := case when v_line.sale_price is not null and v_line.sale_price > 0
      and v_line.sale_price < v_line.regular_price then v_line.sale_price else v_line.regular_price end;

    insert into public.order_items (
      order_id, product_id, variant_id, variant_name, variant_sku,
      variant_attributes, variant_image_url, quantity, price, total
    ) values (
      v_order_id, v_line.product_id, v_line.variant_id,
      case when v_line.variant_id is null then null
        else coalesce(v_line.variant_name, v_line.option_name || ': ' || v_line.option_value) end,
      v_line.variant_sku, v_line.variant_attributes, v_line.variant_image_url,
      v_line.quantity, v_unit_price, round(v_unit_price * v_line.quantity, 2)
    );

    if v_line.variant_id is not null and v_line.variant_stock is not null then
      v_previous_stock := v_line.variant_stock;
      v_new_stock := v_previous_stock - v_line.quantity;
      update public.product_variants set stock = v_new_stock, updated_at = now()
      where id = v_line.variant_id;
    else
      select coalesce(stock, 0) into v_previous_stock
      from public.products where id = v_line.product_id for update;
      v_new_stock := v_previous_stock - v_line.quantity;
      update public.products set stock = v_new_stock where id = v_line.product_id;
    end if;
    update public.products set sold_count = coalesce(sold_count, 0) + v_line.quantity
    where id = v_line.product_id;
    insert into public.inventory_logs(product_id, variant_id, previous_stock, new_stock, change_type, note)
    values (v_line.product_id, v_line.variant_id, v_previous_stock, v_new_stock,
      'adjustment', 'Customer order ' || v_order_number);
  end loop;

  v_customer_name := btrim((p_shipping_address ->> 'first_name') || ' ' || (p_shipping_address ->> 'last_name'));
  v_customer_email := btrim(p_shipping_address ->> 'email');
  v_payment_transaction_code := 'PAY-' || to_char(clock_timestamp(), 'YYYYMMDD') || '-'
    || upper(substr(replace(extensions.uuid_generate_v4()::text, '-', ''), 1, 6));
  insert into public.payment_transactions (
    order_id, payment_method_id, transaction_code, order_number, customer_name,
    customer_email, method_code, method_name, provider, amount, fee_amount,
    currency, status, notes, config
  ) values (
    v_order_id, v_payment.id, v_payment_transaction_code, v_order_number,
    v_customer_name, v_customer_email, v_payment.code, v_payment.name,
    v_payment.provider, v_total, v_payment_fee, 'USD', 'pending',
    v_payment.instructions_en, jsonb_build_object('shipping_method_id', v_shipping.id)
  );
  if p_cart_id is not null then delete from public.cart_items where cart_id = p_cart_id; end if;

  return jsonb_build_object(
    'order_id', v_order_id, 'order_number', v_order_number, 'status', v_status,
    'payment_status', v_payment_status, 'subtotal', v_subtotal,
    'shipping_cost', v_shipping_cost, 'payment_fee', v_payment_fee,
    'discount_amount', 0, 'total', v_total
  );
end;

declare
  v_regular numeric;
  v_sale numeric;
begin
  if new.variant_id is null then return new; end if;
  select coalesce(variant.price, product.price), coalesce(variant.sale_price, product.sale_price)
  into v_regular, v_sale
  from public.product_variants variant
  join public.products product on product.id = variant.product_id
  where variant.id = new.variant_id and variant.product_id = new.product_id;
  if not found then raise exception 'The selected product variant no longer exists.'; end if;
  new.price := case when v_sale is not null and v_sale > 0 and v_sale < v_regular then v_sale else v_regular end;
  new.total := round(new.price * new.quantity, 2);
  return new;
end;

declare
  v_user_id uuid := auth.uid();
  v_settings public.loyalty_program_settings%rowtype;
  v_result jsonb;
  v_order_id uuid;
  v_subtotal numeric(10,2);
  v_shipping public.shipping_methods%rowtype;
  v_payment public.payment_methods%rowtype;
  v_shipping_cost numeric(10,2);
  v_payment_fee numeric(10,2);
  v_total numeric(10,2);
  v_total_points_cost integer := 0;
  v_points_earned integer := 0;
  v_customer_balance integer;
  v_has_redemptions boolean;
  v_already_processed boolean;
begin
  if coalesce(cardinality(p_redeem_product_ids), 0) <> coalesce(
    (select count(distinct requested_id) from unnest(p_redeem_product_ids) requested_id), 0
  ) or coalesce(cardinality(p_redeem_variant_ids), 0) <> coalesce(
    (select count(distinct requested_id) from unnest(p_redeem_variant_ids) requested_id), 0
  ) then
    raise exception 'Duplicate loyalty redemption selections are not allowed.';
  end if;

  v_has_redemptions := coalesce(cardinality(p_redeem_product_ids), 0) > 0
    or coalesce(cardinality(p_redeem_variant_ids), 0) > 0;

  if v_has_redemptions and p_discount_id is not null then
    raise exception 'Loyalty redemption cannot be combined with a promo code.';
  end if;

  -- The existing loyalty checkout remains the source of order creation, idempotency,
  -- variant-aware server pricing, stock reservation, and ordinary points earning.
  -- Redemptions are applied below by exact order-item variant identity.
  v_result := public.place_customer_order(
    p_cart_id, p_shipping_method_id, p_payment_method_id, p_shipping_address,
    p_items, p_customer_notes, p_discount_id, p_discount_code,
    p_expected_subtotal, p_checkout_token, array[]::uuid[]
  );
  v_order_id := (v_result ->> 'order_id')::uuid;

  select variant_loyalty_processed into v_already_processed
  from public.orders where id = v_order_id for update;
  if v_already_processed then
    return v_result || (
      select jsonb_build_object(
        'subtotal', subtotal,
        'shipping_cost', shipping,
        'payment_fee', payment_fee,
        'discount_amount', discount_amount,
        'total', total,
        'loyalty_points_redeemed', loyalty_points_redeemed,
        'loyalty_points_earned', loyalty_points_earned
      ) from public.orders where id = v_order_id
    );
  end if;

  select * into v_settings from public.loyalty_program_settings where id = true;
  if not found then raise exception 'Loyalty settings are unavailable.'; end if;

  if v_has_redemptions then
    if v_user_id is null then raise exception 'Sign in to redeem loyalty points.'; end if;
    if not v_settings.is_enabled then raise exception 'The loyalty program is currently disabled.'; end if;

    if exists (
      select 1
      from public.order_items item
      join public.products product on product.id = item.product_id
      where item.order_id = v_order_id
        and (
          (item.variant_id is null and item.product_id = any(coalesce(p_redeem_product_ids, array[]::uuid[])))
          or item.variant_id = any(coalesce(p_redeem_variant_ids, array[]::uuid[]))
        )
        and product.is_loyalty_eligible is distinct from true
    ) then
      raise exception 'A selected product is not eligible for loyalty redemption.';
    end if;

    if (
      select count(*)
      from public.order_items item
      where item.order_id = v_order_id and (
        (item.variant_id is null and item.product_id = any(coalesce(p_redeem_product_ids, array[]::uuid[])))
        or item.variant_id = any(coalesce(p_redeem_variant_ids, array[]::uuid[]))
      )
    ) <> coalesce(cardinality(p_redeem_product_ids), 0)
       + coalesce(cardinality(p_redeem_variant_ids), 0)
    then
      raise exception 'A loyalty redemption selection is not present in the order.';
    end if;

    select coalesce(sum(ceil((item.price * item.quantity) / v_settings.point_value_usd)), 0)::integer
    into v_total_points_cost
    from public.order_items item
    where item.order_id = v_order_id and (
      (item.variant_id is null and item.product_id = any(coalesce(p_redeem_product_ids, array[]::uuid[])))
      or item.variant_id = any(coalesce(p_redeem_variant_ids, array[]::uuid[]))
    );

    if v_total_points_cost < v_settings.minimum_redemption_points then
      raise exception 'The redemption does not meet the minimum loyalty points requirement.';
    end if;

    insert into public.customer_loyalty_points_balances (user_id, balance)
    values (
      v_user_id,
      coalesce((select sum(points_delta)::integer from public.customer_loyalty_points_ledger
        where user_id = v_user_id), 0)
    ) on conflict (user_id) do nothing;
    select balance into v_customer_balance
    from public.customer_loyalty_points_balances where user_id = v_user_id for update;
    if v_customer_balance < v_total_points_cost then raise exception 'Insufficient loyalty points.'; end if;

    update public.order_items item
    set loyalty_effective_unit_price = item.price,
        loyalty_redeemed = true,
        loyalty_points_cost = ceil((item.price * item.quantity) / v_settings.point_value_usd),
        loyalty_points_earned = 0,
        total = 0
    where item.order_id = v_order_id and (
      (item.variant_id is null and item.product_id = any(coalesce(p_redeem_product_ids, array[]::uuid[])))
      or item.variant_id = any(coalesce(p_redeem_variant_ids, array[]::uuid[]))
    );
  end if;

  select round(coalesce(sum(total), 0), 2) into v_subtotal
  from public.order_items where order_id = v_order_id;
  select * into v_shipping from public.shipping_methods
  where id = p_shipping_method_id and is_active = true;
  v_shipping_cost := coalesce(v_shipping.base_cost, 0);
  if v_shipping.free_shipping_min_amount is not null and v_subtotal >= v_shipping.free_shipping_min_amount then
    v_shipping_cost := 0;
  end if;
  v_shipping_cost := round(v_shipping_cost, 2);
  select * into v_payment from public.payment_methods
  where id = p_payment_method_id and is_active = true;
  v_payment_fee := round(coalesce(v_payment.fee_fixed, 0)
    + ((v_subtotal + v_shipping_cost) * coalesce(v_payment.fee_percentage, 0) / 100), 2);
  v_total := greatest(0, round(v_subtotal + v_shipping_cost + v_payment_fee
    - case when v_has_redemptions then 0 else coalesce((v_result ->> 'discount_amount')::numeric, 0) end, 2));

  if v_user_id is not null and v_settings.is_enabled then
    v_points_earned := floor(v_subtotal * v_settings.points_earned_per_usd);
  end if;
  update public.order_items item
  set loyalty_points_earned = case when item.loyalty_redeemed then 0
    else floor(item.total * v_settings.points_earned_per_usd) end
  where item.order_id = v_order_id;

  update public.orders set
    subtotal = v_subtotal,
    shipping = v_shipping_cost,
    payment_fee = v_payment_fee,
    discount_amount = case when v_has_redemptions then 0 else discount_amount end,
    total = v_total,
    loyalty_points_redeemed = v_total_points_cost,
    loyalty_points_earned = v_points_earned,
    loyalty_point_value_usd = v_settings.point_value_usd,
    loyalty_points_earned_per_usd = v_settings.points_earned_per_usd,
    variant_loyalty_processed = true
  where id = v_order_id;
  update public.payment_transactions set amount = v_total, fee_amount = v_payment_fee
  where order_id = v_order_id;

  if v_total_points_cost > 0 then
    perform public.append_customer_loyalty_ledger_entry(
      v_user_id, v_order_id, null, 'redeem', -v_total_points_cost,
      'Points redeemed for order ' || coalesce(v_result ->> 'order_number', v_order_id::text)
    );
  end if;

  return v_result || jsonb_build_object(
    'subtotal', v_subtotal,
    'shipping_cost', v_shipping_cost,
    'payment_fee', v_payment_fee,
    'discount_amount', case when v_has_redemptions then 0 else coalesce((v_result ->> 'discount_amount')::numeric, 0) end,
    'total', v_total,
    'loyalty_points_redeemed', v_total_points_cost,
    'loyalty_points_earned', v_points_earned
  );
end;

begin
  new.updated_at := now();
  return new;
end;

begin
  if not exists (
    select 1 from public.profiles profile
    join public.roles role on role.id = profile.role_id
    where profile.id = auth.uid()
      and profile.is_active = true
      and role.name in ('admin', 'super_admin')
  ) then
    raise exception 'Admin access is required.';
  end if;

  if not exists (
    select 1 from public.discounts
    where id = p_discount_id and discount_type = 'free_gift'
  ) then
    raise exception 'A free-gift discount is required.';
  end if;

  if coalesce(cardinality(p_product_ids), 0) <> coalesce(
    (select count(distinct product_id) from unnest(p_product_ids) product_id), 0
  ) then
    raise exception 'Duplicate gift products are not allowed.';
  end if;

  delete from public.discount_gift_products where discount_id = p_discount_id;
  insert into public.discount_gift_products(discount_id, product_id, sort_order, is_active)
  select p_discount_id, selected.product_id, selected.ordinality - 1, true
  from unnest(coalesce(p_product_ids, array[]::uuid[]))
    with ordinality as selected(product_id, ordinality);
end;

declare
  v_gift_quantity integer;
  v_ids uuid[];
begin
  if not exists (
    select 1 from public.carts cart
    where cart.id = p_cart_id and cart.user_id = auth.uid()
  ) then
    raise exception 'You do not have access to this cart.';
  end if;
  select gift_quantity into v_gift_quantity from public.discounts
  where id = p_discount_id and discount_type = 'free_gift' and is_active = true;
  if not found then raise exception 'The free-gift promotion is unavailable.'; end if;
  if coalesce(cardinality(p_product_ids), 0) > v_gift_quantity
    or coalesce(cardinality(p_product_ids), 0) <> coalesce(
      (select count(distinct product_id) from unnest(p_product_ids) product_id), 0
    )
  then
    raise exception 'The free-gift selection is invalid.';
  end if;
  if exists (
    select 1 from unnest(coalesce(p_product_ids, array[]::uuid[])) product_id
    left join public.discount_gift_products relation
      on relation.discount_id = p_discount_id and relation.product_id = product_id
    left join public.products product on product.id = product_id
    where relation.id is null or relation.is_active is distinct from true
      or product.is_active is distinct from true or coalesce(product.stock, 0) < 1
  ) then
    raise exception 'This gift is no longer available. Please choose another free gift.';
  end if;

  delete from public.cart_items
  where cart_id = p_cart_id and is_free_gift = true and applied_discount_id = p_discount_id;
  with inserted as (
    insert into public.cart_items(cart_id, product_id, quantity, is_free_gift, applied_discount_id)
    select p_cart_id, product_id, 1, true, p_discount_id
    from unnest(coalesce(p_product_ids, array[]::uuid[])) product_id
    returning id
  ) select coalesce(array_agg(id), array[]::uuid[]) into v_ids from inserted;
  return v_ids;
end;

declare
  v_user_id uuid := auth.uid();
  v_discount public.discounts%rowtype;
  v_result jsonb;
  v_order_id uuid;
  v_order_number text;
  v_paid_subtotal numeric(10,2);
  v_customer_usage integer;
  v_product_id uuid;
  v_product public.products%rowtype;
  v_previous_stock integer;
begin
  if coalesce(cardinality(p_free_gift_product_ids), 0) = 0 then
    return public.place_customer_order(
      p_cart_id, p_shipping_method_id, p_payment_method_id, p_shipping_address,
      p_items, p_customer_notes, p_discount_id, p_discount_code,
      p_expected_subtotal, p_checkout_token, p_redeem_product_ids, p_redeem_variant_ids
    );
  end if;

  if p_discount_id is null or nullif(btrim(p_discount_code), '') is null then
    raise exception 'Apply the free-gift promo code before selecting a gift.';
  end if;

  select * into v_discount from public.discounts where id = p_discount_id for update;
  if not found or v_discount.discount_type <> 'free_gift' then
    raise exception 'The selected free-gift promotion is invalid.';
  end if;
  if upper(btrim(v_discount.code)) <> upper(btrim(p_discount_code)) then
    raise exception 'The applied free-gift promo code is invalid.';
  end if;
  if v_discount.is_active is distinct from true
    or (v_discount.start_date is not null and now() < v_discount.start_date)
    or (v_discount.end_date is not null and now() > v_discount.end_date)
  then
    raise exception 'The free-gift promotion is no longer available.';
  end if;
  if v_discount.usage_limit is not null
    and coalesce(v_discount.usage_count, 0) >= v_discount.usage_limit
  then
    raise exception 'The free-gift promotion has reached its usage limit.';
  end if;
  if cardinality(p_free_gift_product_ids) > v_discount.gift_quantity
    or cardinality(p_free_gift_product_ids) <> (
      select count(distinct gift_id) from unnest(p_free_gift_product_ids) gift_id
    )
  then
    raise exception 'Too many or duplicate free gifts were selected.';
  end if;
  if v_user_id is not null and v_discount.usage_per_customer is not null then
    select count(*) into v_customer_usage from public.orders
    where user_id = v_user_id and discount_id = v_discount.id;
    if v_customer_usage >= v_discount.usage_per_customer then
      raise exception 'You have already used this promo code the maximum number of times.';
    end if;
  end if;
  if p_redeem_product_ids <> array[]::uuid[] or p_redeem_variant_ids <> array[]::uuid[] then
    raise exception 'Loyalty redemption cannot be combined with a free gift.';
  end if;

  if p_cart_id is not null then
    if not exists (
      select 1 from public.carts cart where cart.id = p_cart_id
        and cart.user_id = v_user_id
    ) then
      raise exception 'You do not have access to this cart.';
    end if;
    if (select count(*) from public.cart_items item
        where item.cart_id = p_cart_id and item.is_free_gift = false)
      <> jsonb_array_length(p_items)
      or exists (
        select 1 from public.cart_items cart_item
        where cart_item.cart_id = p_cart_id and cart_item.is_free_gift = false
          and not exists (
            select 1 from jsonb_array_elements(p_items) submitted
            where (submitted ->> 'product_id')::uuid = cart_item.product_id
              and nullif(submitted ->> 'variant_id', '')::uuid is not distinct from cart_item.variant_id
              and (submitted ->> 'quantity')::integer = cart_item.quantity
          )
      )
    then
      raise exception 'Submitted paid items do not match the current cart.';
    end if;
    if (select count(*) from public.cart_items item
        where item.cart_id = p_cart_id and item.is_free_gift = true
          and item.applied_discount_id = p_discount_id)
      <> cardinality(p_free_gift_product_ids)
    then
      raise exception 'The selected gift does not match the current cart.';
    end if;
    if exists (
      select 1 from public.cart_items item
      where item.cart_id = p_cart_id and item.is_free_gift = true
        and (item.applied_discount_id <> p_discount_id
          or item.product_id <> all(p_free_gift_product_ids))
    ) then
      raise exception 'The selected gift does not match the current cart.';
    end if;
  end if;

  if exists (
    select 1 from unnest(p_free_gift_product_ids) gift_id
    left join public.discount_gift_products relation
      on relation.discount_id = p_discount_id and relation.product_id = gift_id
    left join public.products product on product.id = gift_id
    where relation.id is null or relation.is_active is distinct from true
      or product.id is null or product.is_active is distinct from true
      or coalesce(product.stock, 0) < 1
  ) then
    raise exception 'This gift is no longer available. Please choose another free gift.';
  end if;

  v_result := public.place_customer_order(
    null, p_shipping_method_id, p_payment_method_id, p_shipping_address,
    p_items, p_customer_notes, null, null, p_expected_subtotal,
    p_checkout_token, p_redeem_product_ids, p_redeem_variant_ids
  );
  v_order_id := (v_result ->> 'order_id')::uuid;
  v_paid_subtotal := (v_result ->> 'subtotal')::numeric;
  v_order_number := v_result ->> 'order_number';

  if v_paid_subtotal < coalesce(v_discount.minimum_order_amount, 0) then
    raise exception 'The order no longer meets the free-gift minimum amount.';
  end if;

  if not (select free_gift_processed from public.orders where id = v_order_id for update) then
    foreach v_product_id in array p_free_gift_product_ids loop
      select * into v_product from public.products where id = v_product_id for update;
      if not found or v_product.is_active is distinct from true or coalesce(v_product.stock, 0) < 1 then
        raise exception 'This gift is no longer available. Please choose another free gift.';
      end if;
      v_previous_stock := coalesce(v_product.stock, 0);
      insert into public.order_items(
        order_id, product_id, quantity, price, total, original_unit_price,
        is_free_gift, applied_discount_id, loyalty_points_earned
      ) values (
        v_order_id, v_product.id, 1, 0, 0,
        case when v_product.sale_price is not null and v_product.sale_price > 0
          and v_product.sale_price < v_product.price then v_product.sale_price else v_product.price end,
        true, v_discount.id, 0
      );
      update public.products set stock = v_previous_stock - 1,
        sold_count = coalesce(sold_count, 0) + 1 where id = v_product.id;
      insert into public.inventory_logs(product_id, previous_stock, new_stock, change_type, note)
      values (v_product.id, v_previous_stock, v_previous_stock - 1,
        'adjustment', 'Free gift for customer order ' || v_order_number);
    end loop;

    update public.orders set cart_id = p_cart_id, discount_id = v_discount.id,
      discount_code = v_discount.code, discount_amount = 0, free_gift_processed = true
    where id = v_order_id;
    update public.discounts set usage_count = coalesce(usage_count, 0) + 1,
      updated_at = now() where id = v_discount.id;
    if p_cart_id is not null then delete from public.cart_items where cart_id = p_cart_id; end if;
  end if;

  return v_result || jsonb_build_object(
    'discount_id', v_discount.id,
    'discount_code', v_discount.code,
    'discount_amount', 0
  );
end;

declare
  v_user_id uuid := auth.uid();
  v_discount public.discounts%rowtype;
  v_result jsonb;
  v_order public.orders%rowtype;
  v_shipping public.shipping_methods%rowtype;
  v_payment public.payment_methods%rowtype;
  v_eligible_subtotal numeric(10,2) := 0;
  v_shipping_cost numeric(10,2);
  v_payment_fee numeric(10,2);
  v_total numeric(10,2);
  v_customer_usage integer := 0;
begin
  if (p_discount_id is null) <> (nullif(btrim(p_discount_code), '') is null) then
    raise exception 'The applied promo information is incomplete. Remove it or apply it again.';
  end if;

  if p_discount_id is not null then
    select * into v_discount
    from public.discounts
    where id = p_discount_id
    for update;
    if not found then raise exception 'The applied promo code no longer exists.'; end if;
  end if;

  if p_discount_id is not null and v_discount.discount_type = 'free_shipping' then
    if upper(btrim(v_discount.code)) <> upper(btrim(p_discount_code)) then
      raise exception 'The applied promo code is invalid. Remove it or apply it again.';
    end if;
    if v_discount.is_active is distinct from true then
      raise exception 'The applied promo code is no longer active.';
    end if;
    if v_discount.start_date is not null and now() < v_discount.start_date then
      raise exception 'The applied promo code is not active yet.';
    end if;
    if v_discount.end_date is not null and now() > v_discount.end_date then
      raise exception 'The applied promo code has expired.';
    end if;
    if v_discount.usage_limit is not null
      and coalesce(v_discount.usage_count, 0) >= v_discount.usage_limit
    then
      raise exception 'The applied promo code has reached its usage limit.';
    end if;
    if coalesce(cardinality(p_free_gift_product_ids), 0) > 0 then
      raise exception 'A free-shipping promotion cannot include free-gift products.';
    end if;
    if coalesce(cardinality(p_redeem_product_ids), 0) > 0
      or coalesce(cardinality(p_redeem_variant_ids), 0) > 0
    then
      raise exception 'Loyalty redemption cannot be combined with a promo code.';
    end if;

    -- The existing checkout remains responsible for cart matching, pricing,
    -- stock, idempotency, order creation, and ordinary loyalty earning.
    v_result := public.place_customer_order_legacy_shipping_threshold(
      p_cart_id, p_shipping_method_id, p_payment_method_id, p_shipping_address,
      p_items, p_customer_notes, null, null, p_expected_subtotal,
      p_checkout_token, p_redeem_product_ids, p_redeem_variant_ids,
      array[]::uuid[]
    );
  else
    v_result := public.place_customer_order_legacy_shipping_threshold(
      p_cart_id, p_shipping_method_id, p_payment_method_id, p_shipping_address,
      p_items, p_customer_notes, p_discount_id, p_discount_code,
      p_expected_subtotal, p_checkout_token, p_redeem_product_ids,
      p_redeem_variant_ids, p_free_gift_product_ids
    );
  end if;

  select * into v_order
  from public.orders
  where id = (v_result ->> 'order_id')::uuid
  for update;
  if not found then raise exception 'The placed order could not be loaded.'; end if;

  select * into v_shipping
  from public.shipping_methods
  where id = p_shipping_method_id and is_active = true;
  if not found then raise exception 'Selected shipping method is not available.'; end if;

  select * into v_payment
  from public.payment_methods
  where id = p_payment_method_id and is_active = true;
  if not found then raise exception 'Selected payment method is not available.'; end if;

  if p_discount_id is not null and v_discount.discount_type = 'free_shipping' then
    if v_order.subtotal < coalesce(v_discount.minimum_order_amount, 0) then
      raise exception 'The order no longer meets the promo code minimum amount.';
    end if;

    if v_discount.applies_to = 'all' then
      v_eligible_subtotal := v_order.subtotal;
    elsif v_discount.applies_to = 'product' then
      select coalesce(sum(item.total), 0) into v_eligible_subtotal
      from public.order_items item
      where item.order_id = v_order.id
        and item.is_free_gift = false
        and item.product_id = v_discount.product_id;
    elsif v_discount.applies_to = 'category' then
      select coalesce(sum(item.total), 0) into v_eligible_subtotal
      from public.order_items item
      join public.products product on product.id = item.product_id
      where item.order_id = v_order.id
        and item.is_free_gift = false
        and product.category_id = v_discount.category_id;
    else
      raise exception 'The applied promo code has an unsupported eligibility rule.';
    end if;
    if v_eligible_subtotal <= 0 then
      raise exception 'The applied promo code is not valid for the products in this order.';
    end if;

    if v_user_id is not null and v_discount.usage_per_customer is not null then
      select count(*) into v_customer_usage
      from public.orders
      where user_id = v_user_id and discount_id = v_discount.id;
      if v_customer_usage >= v_discount.usage_per_customer then
        raise exception 'You have already used this promo code the maximum number of times.';
      end if;
    end if;

    if not v_order.free_shipping_discount_processed then
      update public.discounts
      set usage_count = coalesce(usage_count, 0) + 1, updated_at = now()
      where id = v_discount.id;
      update public.orders
      set discount_id = v_discount.id,
          discount_code = v_discount.code,
          discount_amount = 0,
          free_shipping_discount_processed = true
      where id = v_order.id;
      v_order.discount_id := v_discount.id;
      v_order.discount_code := v_discount.code;
      v_order.discount_amount := 0;
    end if;
    v_shipping_cost := 0;
  else
    -- A configured zero base cost (for example pickup) remains free. No name or
    -- code convention is needed to identify that method.
    v_shipping_cost := round(coalesce(v_shipping.base_cost, 0), 2);
  end if;

  if v_payment.min_amount is not null
    and v_order.subtotal + v_shipping_cost < v_payment.min_amount
  then
    raise exception 'Selected payment method minimum amount is not met.';
  end if;
  if v_payment.max_amount is not null
    and v_order.subtotal + v_shipping_cost > v_payment.max_amount
  then
    raise exception 'Selected payment method maximum amount is exceeded.';
  end if;

  v_payment_fee := round(
    coalesce(v_payment.fee_fixed, 0)
      + ((v_order.subtotal + v_shipping_cost) * coalesce(v_payment.fee_percentage, 0) / 100),
    2
  );
  v_total := greatest(0, round(
    v_order.subtotal + v_shipping_cost + v_payment_fee - coalesce(v_order.discount_amount, 0),
    2
  ));

  update public.orders
  set shipping = v_shipping_cost,
      payment_fee = v_payment_fee,
      total = v_total
  where id = v_order.id;

  update public.payment_transactions
  set amount = v_total, fee_amount = v_payment_fee
  where order_id = v_order.id;

  return v_result || jsonb_build_object(
    'discount_id', v_order.discount_id,
    'discount_code', v_order.discount_code,
    'discount_amount', coalesce(v_order.discount_amount, 0),
    'shipping_cost', v_shipping_cost,
    'payment_fee', v_payment_fee,
    'total', v_total
  );
end;

begin
  if tg_op = 'INSERT' then
    new.sold_count := 0;
  elsif pg_trigger_depth() = 1 then
    new.sold_count := old.sold_count;
  end if;

  return new;
end;

declare
  v_is_successful boolean := lower(coalesce(new.status, '')) in ('delivered', 'completed');
  v_is_reversed boolean := lower(coalesce(new.status, '')) in (
    'cancelled', 'canceled', 'refunded', 'returned'
  ) or lower(coalesce(new.payment_status, '')) = 'refunded';
begin
  if v_is_reversed and new.sales_processed then
    update public.products product
    set sold_count = greatest(0, coalesce(product.sold_count, 0) - sold.quantity)
    from (
      select item.product_id, sum(greatest(coalesce(item.quantity, 0), 0))::integer as quantity
      from public.order_items item
      where item.order_id = new.id
      group by item.product_id
    ) sold
    where product.id = sold.product_id;

    update public.orders
    set sales_processed = false
    where id = new.id;
  elsif v_is_successful and not new.sales_processed then
    update public.products product
    set sold_count = coalesce(product.sold_count, 0) + sold.quantity
    from (
      select item.product_id, sum(greatest(coalesce(item.quantity, 0), 0))::integer as quantity
      from public.order_items item
      where item.order_id = new.id
      group by item.product_id
    ) sold
    where product.id = sold.product_id;

    update public.orders
    set sales_processed = true
    where id = new.id;
  end if;

  return new;
end;

begin
  new.updated_at := now();
  return new;
end;

begin
  if not exists (
    select 1
    from public.profiles profile
    join public.roles role on role.id = profile.role_id
    where profile.id = auth.uid()
      and profile.is_active = true
      and role.name in ('admin', 'super_admin')
  ) then
    raise exception 'Admin access is required.';
  end if;

  if p_model <> 'onnx-community/dinov2-small-ONNX' or p_embedding_version <> 1 then
    raise exception 'Unsupported image embedding configuration.';
  end if;

  if not exists (
    select 1 from public.products product
    where product.id = p_product_id and product.image_url = p_image_url
  ) then
    raise exception 'The product image changed before indexing completed.';
  end if;

  insert into public.product_image_embeddings (
    product_id, image_url, embedding, model, embedding_version
  ) values (
    p_product_id, p_image_url, p_embedding, p_model, p_embedding_version
  )
  on conflict (product_id) do update set
    image_url = excluded.image_url,
    embedding = excluded.embedding,
    model = excluded.model,
    embedding_version = excluded.embedding_version,
    updated_at = now();
end;

begin
  if not exists (
    select 1
    from public.profiles profile
    join public.roles role on role.id = profile.role_id
    where profile.id = auth.uid()
      and profile.is_active = true
      and role.name in ('admin', 'super_admin')
  ) then
    raise exception 'Admin access is required.';
  end if;

  delete from public.product_image_embeddings where product_id = p_product_id;
end;

declare
  customer_role_id uuid;
  provisioned_role text;
begin
  -- raw_app_meta_data can only be assigned by the trusted Admin API/service role.
  -- Public callers can modify raw_user_meta_data, so it never controls roles.
  provisioned_role := lower(coalesce(new.raw_app_meta_data ->> 'role', ''));
  if provisioned_role in ('admin', 'super_admin', 'staff') then
    return new;
  end if;

  select id into customer_role_id
  from public.roles
  where name = 'customer'
  limit 1;

  if customer_role_id is null then
    raise exception using
      errcode = 'P0001',
      message = 'Customer role is not configured.';
  end if;

  insert into public.profiles (
    id,
    role_id,
    full_name,
    email,
    phone,
    avatar_url,
    is_active
  ) values (
    new.id,
    customer_role_id,
    nullif(
      trim(
        coalesce(
          new.raw_user_meta_data ->> 'full_name',
          new.raw_user_meta_data ->> 'name',
          ''
        )
      ),
      ''
    ),
    new.email,
    nullif(trim(coalesce(new.raw_user_meta_data ->> 'phone', '')), ''),
    nullif(
      trim(
        coalesce(
          new.raw_user_meta_data ->> 'avatar_url',
          new.raw_user_meta_data ->> 'picture',
          ''
        )
      ),
      ''
    ),
    true
  )
  on conflict (id) do nothing;

  return new;
end;

declare
  v_item public.order_items%rowtype;
  v_previous_stock integer;
  v_new_stock integer;
  v_variant_stock_found boolean := false;
begin
  select *
  into v_item
  from public.order_items
  where id = p_order_item_id
  for update;

  if not found then
    return false;
  end if;

  if v_item.inventory_restored_at is not null then
    return false;
  end if;

  if v_item.variant_id is not null then
    select stock
    into v_previous_stock
    from public.product_variants
    where id = v_item.variant_id
    for update;

    v_variant_stock_found := found and v_previous_stock is not null;
  end if;

  if v_variant_stock_found then
    v_new_stock := v_previous_stock + greatest(coalesce(v_item.quantity, 0), 0);

    update public.product_variants
    set stock = v_new_stock,
        updated_at = now()
    where id = v_item.variant_id;
  else
    select coalesce(stock, 0)
    into v_previous_stock
    from public.products
    where id = v_item.product_id
    for update;

    if not found then
      raise exception 'The order item product no longer exists.';
    end if;

    v_new_stock := v_previous_stock + greatest(coalesce(v_item.quantity, 0), 0);

    update public.products
    set stock = v_new_stock
    where id = v_item.product_id;
  end if;

  if v_item.is_free_gift is distinct from true then
    update public.products
    set sold_count = greatest(
      0,
      coalesce(sold_count, 0) - greatest(coalesce(v_item.quantity, 0), 0)
    )
    where id = v_item.product_id;
  end if;

  insert into public.inventory_logs (
    product_id,
    variant_id,
    previous_stock,
    new_stock,
    change_type,
    note
  ) values (
    v_item.product_id,
    v_item.variant_id,
    v_previous_stock,
    v_new_stock,
    'return',
    nullif(btrim(p_note), '')
  );

  update public.order_items
  set inventory_restored_at = now()
  where id = v_item.id;

  return true;
end;

declare
  v_order public.orders%rowtype;
  v_discount public.discounts%rowtype;
  v_item_id uuid;
  v_item_count integer := 0;
  v_subtotal numeric(10,2) := 0;
  v_shipping numeric(10,2) := 0;
  v_payment_fee numeric(10,2) := 0;
  v_discount_amount numeric(10,2) := 0;
  v_eligible_subtotal numeric(10,2) := 0;
  v_total numeric(10,2) := 0;
  v_loyalty_points_redeemed integer := 0;
  v_loyalty_points_earned integer := 0;
  v_points_rate numeric(10,2) := 1;
  v_clear_discount boolean := false;
begin
  select *
  into v_order
  from public.orders
  where id = p_order_id
  for update;

  if not found then
    raise exception 'Order not found.';
  end if;

  select count(*)::integer, round(coalesce(sum(item.total), 0), 2)
  into v_item_count, v_subtotal
  from public.order_items item
  where item.order_id = p_order_id;

  if v_item_count > 0 and v_order.discount_id is not null then
    select *
    into v_discount
    from public.discounts
    where id = v_order.discount_id
    for update;

    if not found or v_subtotal < coalesce(v_discount.minimum_order_amount, 0) then
      v_clear_discount := true;
    elsif v_discount.discount_type in ('percentage', 'fixed_amount') then
      if v_discount.applies_to = 'all' then
        select round(coalesce(sum(item.total), 0), 2)
        into v_eligible_subtotal
        from public.order_items item
        where item.order_id = p_order_id;
      elsif v_discount.applies_to = 'product' then
        select round(coalesce(sum(item.total), 0), 2)
        into v_eligible_subtotal
        from public.order_items item
        where item.order_id = p_order_id
          and item.product_id = v_discount.product_id;
      elsif v_discount.applies_to = 'category' then
        select round(coalesce(sum(item.total), 0), 2)
        into v_eligible_subtotal
        from public.order_items item
        join public.products product on product.id = item.product_id
        where item.order_id = p_order_id
          and product.category_id = v_discount.category_id;
      else
        v_clear_discount := true;
      end if;

      if not v_clear_discount and v_eligible_subtotal <= 0 then
        v_clear_discount := true;
      elsif not v_clear_discount and v_discount.discount_type = 'percentage' then
        v_discount_amount := round(
          v_eligible_subtotal * coalesce(v_discount.discount_value, 0) / 100,
          2
        );
      elsif not v_clear_discount then
        v_discount_amount := round(coalesce(v_discount.discount_value, 0), 2);
      end if;

      v_discount_amount := least(
        v_eligible_subtotal,
        greatest(0, v_discount_amount)
      );
    elsif v_discount.discount_type not in ('free_shipping', 'free_gift') then
      v_clear_discount := true;
    end if;
  elsif v_order.discount_id is not null then
    v_clear_discount := true;
  end if;

  if v_clear_discount and v_order.discount_id is not null then
    if v_discount.discount_type = 'free_gift' then
      for v_item_id in
        select item.id
        from public.order_items item
        where item.order_id = p_order_id
          and item.is_free_gift = true
        order by item.id
        for update
      loop
        perform public.restore_admin_order_item_inventory(
          v_item_id,
          'Free gift removed after admin order update ' || coalesce(v_order.order_number, v_order.id::text)
        );

        delete from public.order_items where id = v_item_id;
      end loop;

      select count(*)::integer, round(coalesce(sum(item.total), 0), 2)
      into v_item_count, v_subtotal
      from public.order_items item
      where item.order_id = p_order_id;
    end if;

    update public.discounts
    set usage_count = greatest(0, coalesce(usage_count, 0) - 1),
        updated_at = now()
    where id = v_order.discount_id;

    v_discount_amount := 0;
  end if;

  if v_item_count > 0 then
    select round(coalesce(base_cost, v_order.shipping, 0), 2)
    into v_shipping
    from public.shipping_methods
    where id = v_order.shipping_method_id;

    if not found then
      v_shipping := round(coalesce(v_order.shipping, 0), 2);
    end if;

    if not v_clear_discount and v_discount.discount_type = 'free_shipping' then
      v_shipping := 0;
    end if;

    select round(
      coalesce(fee_fixed, 0)
        + ((v_subtotal + v_shipping) * coalesce(fee_percentage, 0) / 100),
      2
    )
    into v_payment_fee
    from public.payment_methods
    where id = v_order.payment_method_id;

    if not found then
      v_payment_fee := round(coalesce(v_order.payment_fee, 0), 2);
    end if;

    v_total := greatest(
      0,
      round(v_subtotal + v_shipping + v_payment_fee - v_discount_amount, 2)
    );
  end if;

  select coalesce(sum(item.loyalty_points_cost), 0)::integer
  into v_loyalty_points_redeemed
  from public.order_items item
  where item.order_id = p_order_id;

  v_points_rate := coalesce(v_order.loyalty_points_earned_per_usd, 1);

  v_loyalty_points_earned := floor(v_subtotal * v_points_rate)::integer;

  update public.order_items item
  set loyalty_points_earned = case
    when item.loyalty_redeemed then 0
    else floor(item.total * v_points_rate)::integer
  end
  where item.order_id = p_order_id;

  update public.orders
  set subtotal = v_subtotal,
      shipping = v_shipping,
      payment_fee = v_payment_fee,
      discount_id = case when v_clear_discount then null else discount_id end,
      discount_code = case when v_clear_discount then null else discount_code end,
      discount_amount = v_discount_amount,
      total = v_total,
      loyalty_points_redeemed = v_loyalty_points_redeemed,
      loyalty_points_earned = v_loyalty_points_earned,
      free_gift_processed = case when v_clear_discount then false else free_gift_processed end,
      free_shipping_discount_processed = case
        when v_clear_discount then false
        else free_shipping_discount_processed
      end,
      status = case when v_item_count = 0 then 'cancelled' else status end
  where id = p_order_id;

  update public.payment_transactions
  set amount = v_total,
      fee_amount = v_payment_fee
  where order_id = p_order_id;
end;

declare
  v_order public.orders%rowtype;
  v_item public.order_items%rowtype;
  v_updated_order public.orders%rowtype;
  v_previous_loyalty_points_earned integer;
  v_loyalty_delta integer;
begin
  if not exists (
    select 1
    from public.profiles profile
    join public.roles role on role.id = profile.role_id
    where profile.id = auth.uid()
      and role.name in ('admin', 'super_admin')
      and profile.is_active = true
  ) then
    raise exception 'Admin access is required.';
  end if;

  select *
  into v_order
  from public.orders
  where id = p_order_id
  for update;

  if not found then
    raise exception 'Order not found.';
  end if;

  select *
  into v_item
  from public.order_items
  where id = p_order_item_id
    and order_id = p_order_id
  for update;

  if not found then
    raise exception 'Order item not found or was already removed.';
  end if;

  v_previous_loyalty_points_earned := coalesce(v_order.loyalty_points_earned, 0);

  perform public.restore_admin_order_item_inventory(
    v_item.id,
    'Admin removed item from order ' || coalesce(v_order.order_number, v_order.id::text)
  );

  delete from public.order_items where id = v_item.id;

  perform public.recalculate_admin_order_after_item_change(p_order_id);

  select *
  into v_updated_order
  from public.orders
  where id = p_order_id;

  if v_order.user_id is not null and coalesce(v_item.loyalty_points_cost, 0) > 0 then
    perform public.append_customer_loyalty_ledger_entry(
      v_order.user_id,
      v_order.id,
      null,
      'adjustment',
      v_item.loyalty_points_cost,
      'Redeemed points restored for removed order item in '
        || coalesce(v_order.order_number, v_order.id::text)
    );
  end if;

  if lower(coalesce(v_updated_order.status, '')) in ('delivered', 'completed')
    and v_order.user_id is not null
    and exists (
      select 1
      from public.customer_loyalty_points_ledger
      where user_id = v_order.user_id
        and order_id = v_order.id
        and transaction_type = 'earn'
    )
  then
    v_loyalty_delta := coalesce(v_updated_order.loyalty_points_earned, 0)
      - v_previous_loyalty_points_earned;

    if v_loyalty_delta <> 0 then
      perform public.append_customer_loyalty_ledger_entry(
        v_order.user_id,
        v_order.id,
        null,
        'adjustment',
        v_loyalty_delta,
        'Loyalty points adjusted after removing an item from order '
          || coalesce(v_order.order_number, v_order.id::text)
      );
    end if;
  end if;

  return jsonb_build_object(
    'order_id', v_updated_order.id,
    'status', v_updated_order.status,
    'subtotal', v_updated_order.subtotal,
    'discount_amount', v_updated_order.discount_amount,
    'shipping', v_updated_order.shipping,
    'payment_fee', v_updated_order.payment_fee,
    'total', v_updated_order.total
  );
end;

declare
  v_order public.orders%rowtype;
  v_item_id uuid;
begin
  if not exists (
    select 1
    from public.profiles profile
    join public.roles role on role.id = profile.role_id
    where profile.id = auth.uid()
      and role.name in ('admin', 'super_admin')
      and profile.is_active = true
  ) then
    raise exception 'Admin access is required.';
  end if;

  if lower(p_status) not in (
    'pending', 'processing', 'shipped', 'delivered', 'completed', 'cancelled', 'canceled', 'returned'
  ) then
    raise exception 'Unsupported order status.';
  end if;

  if lower(p_payment_status) not in ('pending', 'unpaid', 'paid', 'failed', 'refunded') then
    raise exception 'Unsupported payment status.';
  end if;

  select *
  into v_order
  from public.orders
  where id = p_order_id
  for update;

  if not found then
    raise exception 'Order not found.';
  end if;

  if lower(p_status) in ('cancelled', 'canceled') then
    for v_item_id in
      select item.id
      from public.order_items item
      where item.order_id = p_order_id
        and item.inventory_restored_at is null
      order by item.id
      for update
    loop
      perform public.restore_admin_order_item_inventory(
        v_item_id,
        'Admin cancelled order ' || coalesce(v_order.order_number, v_order.id::text)
      );
    end loop;
  end if;

  update public.orders
  set status = lower(p_status),
      payment_status = lower(p_payment_status)
  where id = p_order_id;
end;

policies.statement:
create policy "Public can read published reviews"
on public.reviews for select
using (status = 'published');

create policy "Customers can read own reviews"
on public.reviews for select to authenticated
using (user_id = auth.uid());

create policy "Admins can manage reviews"
on public.reviews for all to authenticated
using (
  exists (
    select 1 from public.profiles p
    join public.roles r on r.id = p.role_id
    where p.id = auth.uid() and r.name in ('admin', 'super_admin')
  )
)
with check (
  exists (
    select 1 from public.profiles p
    join public.roles r on r.id = p.role_id
    where p.id = auth.uid() and r.name in ('admin', 'super_admin')
  )
);

create policy "Customers update own cart items" on public.cart_items for update to authenticated
using (exists (select 1 from public.carts where carts.id = cart_items.cart_id and carts.user_id = auth.uid()))
with check (exists (select 1 from public.carts where carts.id = cart_items.cart_id and carts.user_id = auth.uid()));

create policy "Admins can read profiles"
  on public.profiles
  for select to authenticated
  using (
    exists (
      select 1 from public.profiles p
      join public.roles r on r.id = p.role_id
      where p.id = auth.uid() and r.name in ('admin', 'super_admin')
    )
  );

create policy "admins can update loyalty settings"
on public.loyalty_program_settings for update
to authenticated
using (exists (
  select 1 from public.profiles profile
  join public.roles role on role.id = profile.role_id
  where profile.id = auth.uid() and role.name in ('admin', 'super_admin')
))
with check (id = true);

create policy "customers can read their loyalty ledger"
on public.customer_loyalty_points_ledger for select
to authenticated
using (
  user_id = auth.uid()
  or exists (
    select 1 from public.profiles profile
    join public.roles role on role.id = profile.role_id
    where profile.id = auth.uid() and role.name in ('admin', 'super_admin')
  )
);

create policy "Customers can update their addresses"
  on public.customer_addresses for update
  to authenticated
  using (user_id = auth.uid())
  with check (user_id = auth.uid());

create policy "Public can read active product variants"
  on public.product_variants for select to anon, authenticated
  using (
    is_active = true
    and exists (
      select 1 from public.products product
      where product.id = product_id and product.is_active = true
    )
  );

create policy "Admins can manage product variants"
  on public.product_variants for all to authenticated
  using (
    exists (
      select 1 from public.profiles profile
      join public.roles role on role.id = profile.role_id
      where profile.id = auth.uid() and role.name in ('admin', 'super_admin')
    )
  )
  with check (
    exists (
      select 1 from public.profiles profile
      join public.roles role on role.id = profile.role_id
      where profile.id = auth.uid() and role.name in ('admin', 'super_admin')
    )
  );

create policy "Public can read published customer content"
  on public.customer_content_pages for select to anon, authenticated
  using (is_active = true and is_published = true);

create policy "Admins can manage customer content"
  on public.customer_content_pages for all to authenticated
  using (
    exists (
      select 1
      from public.profiles profile
      join public.roles role on role.id = profile.role_id
      where profile.id = auth.uid() and role.name in ('admin', 'super_admin')
    )
  )
  with check (
    exists (
      select 1
      from public.profiles profile
      join public.roles role on role.id = profile.role_id
      where profile.id = auth.uid() and role.name in ('admin', 'super_admin')
    )
  );

create policy "Public can read active customer FAQs"
  on public.customer_faqs for select to anon, authenticated
  using (is_active = true);

create policy "Admins can manage customer FAQs"
  on public.customer_faqs for all to authenticated
  using (
    exists (
      select 1
      from public.profiles profile
      join public.roles role on role.id = profile.role_id
      where profile.id = auth.uid() and role.name in ('admin', 'super_admin')
    )
  )
  with check (
    exists (
      select 1
      from public.profiles profile
      join public.roles role on role.id = profile.role_id
      where profile.id = auth.uid() and role.name in ('admin', 'super_admin')
    )
  );

create policy "Anonymous visitors can submit contact messages"
  on public.customer_contact_messages for insert to anon
  with check (customer_user_id is null and status = 'new');

create policy "Customers can submit contact messages"
  on public.customer_contact_messages for insert to authenticated
  with check ((customer_user_id is null or customer_user_id = auth.uid()) and status = 'new');

create policy "Admins can manage customer contact messages"
  on public.customer_contact_messages for all to authenticated
  using (
    exists (
      select 1
      from public.profiles profile
      join public.roles role on role.id = profile.role_id
      where profile.id = auth.uid() and role.name in ('admin', 'super_admin')
    )
  )
  with check (
    exists (
      select 1
      from public.profiles profile
      join public.roles role on role.id = profile.role_id
      where profile.id = auth.uid() and role.name in ('admin', 'super_admin')
    )
  );

create policy "Admins manage gift products"
  on public.discount_gift_products for all to authenticated
  using (
    exists (
      select 1 from public.profiles profile
      join public.roles role on role.id = profile.role_id
      where profile.id = auth.uid()
        and profile.is_active = true
        and role.name in ('admin', 'super_admin')
    )
  )
  with check (
    exists (
      select 1 from public.profiles profile
      join public.roles role on role.id = profile.role_id
      where profile.id = auth.uid()
        and profile.is_active = true
        and role.name in ('admin', 'super_admin')
    )
  );

create policy "Admins can read product image embeddings"
  on public.product_image_embeddings for select to authenticated
  using (
    exists (
      select 1
      from public.profiles profile
      join public.roles role on role.id = profile.role_id
      where profile.id = auth.uid()
        and profile.is_active = true
        and role.name in ('admin', 'super_admin')
    )
  );

