triggers_and_function_changes.statement:
create trigger on_public_customer_signup
after insert on auth.users
for each row execute function public.handle_public_customer_signup();

create trigger protect_customer_profile_privileges
before update on public.profiles
for each row execute function public.prevent_customer_profile_privilege_changes();

create trigger prevent_loyalty_ledger_mutation
before update or delete on public.customer_loyalty_points_ledger
for each row execute function public.prevent_loyalty_ledger_mutation();

create trigger process_order_loyalty_status_change
after update of status, payment_status on public.orders
for each row execute function public.process_order_loyalty_status_change();

create trigger prepare_customer_address_row
before insert or update on public.customer_addresses
for each row execute function public.prepare_customer_address();

create trigger promote_customer_address_after_delete_row
after delete on public.customer_addresses
for each row execute function public.promote_customer_address_after_delete();

create trigger enforce_variant_order_item_price
before update of price on public.order_items
for each row when (new.variant_id is not null)
execute function public.enforce_variant_order_item_price();

create trigger set_customer_content_pages_updated_at
before update on public.customer_content_pages
for each row execute function public.set_customer_help_updated_at();

create trigger set_customer_faqs_updated_at
before update on public.customer_faqs
for each row execute function public.set_customer_help_updated_at();

create trigger set_customer_contact_messages_updated_at
before update on public.customer_contact_messages
for each row execute function public.set_customer_help_updated_at();

alter function public.place_customer_order(
  uuid, uuid, uuid, jsonb, jsonb, text, uuid, text, numeric, uuid, uuid[], uuid[], uuid[]
) rename to place_customer_order_legacy_shipping_threshold;

create trigger protect_product_sold_count
before insert or update of sold_count on public.products
for each row execute function public.protect_product_sold_count();

create trigger process_order_product_sales_status_change
after update of status, payment_status on public.orders
for each row execute function public.process_order_product_sales_status_change();

create trigger set_product_image_embedding_updated_at
before update on public.product_image_embeddings
for each row execute function public.set_product_image_embedding_updated_at();
